window.BIOMASTER.MCQ_MENDEL = [{"id":"MCQ-MD-001","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Mendel","q":"Cho phép lai $P: AaBbDd \\times AaBbdd$ (trội hoàn toàn, PLĐL). Tỉ lệ đời con $F_1$ có kiểu hình $(A-B-dd)$ và tỉ lệ kiểu gen $AaBbDd$ lần lượt là:","opts":["$\\frac{9}{32}$ và $\\frac{1}{8}$.","$\\frac{9}{32}$ và $\\frac{1}{16}$.","$\\frac{9}{64}$ và $\\frac{1}{8}$.","$\\frac{27}{64}$ và $\\frac{1}{8}$."],"ans":0,"exp":"$A-B-dd = \\frac{3}{4} \\times \\frac{3}{4} \\times \\frac{1}{2} = \\frac{9}{32}$. $AaBbDd = \\frac{1}{2} \\times \\frac{1}{2} \\times \\frac{1}{2} = \\frac{1}{8}$."},{"id":"MCQ-MD-002","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tương tác gen","q":"Cho cây hoa đỏ ($AaBb$) tự thụ phấn thu được $F_1$ có tỉ lệ $9$ đỏ : $6$ vàng : $1$ trắng. Nếu lấy cây hoa đỏ $F_1$ có kiểu gen dị hợp 2 cặp đem lai phân tích thì tỉ lệ kiểu hình ở đời con là:","opts":["$1$ đỏ : $2$ vàng : $1$ trắng.","$1$ đỏ : $3$ trắng.","$3$ đỏ : $1$ trắng.","$1$ đỏ : $1$ vàng : $2$ trắng."],"ans":0,"exp":"$AaBb \\times aabb \\rightarrow 1 AaBb$ (đỏ) : $1 Aabb + 1 aaBb$ (2 vàng) : $1 aabb$ (trắng)."},{"id":"MCQ-MD-003","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Liên kết giới tính","q":"Ở ruồi giấm, alen $A$ quy định mắt đỏ trội hoàn toàn so với $a$ quy định mắt trắng nằm trên vùng không tương đồng của NST X. Phép lai nào sau đây cho đời con $F_1$ có 100% ruồi cái mắt đỏ và 100% ruồi đực mắt trắng?","opts":["♀ $X^a X^a \\times$ ♂ $X^A Y$.","♀ $X^A X^a \\times$ ♂ $X^A Y$.","♀ $X^A X^a \\times$ ♂ $X^a Y$.","♀ $X^A X^A \\times$ ♂ $X^a Y$."],"ans":0,"exp":"Di truyền chéo: Mẹ mắt trắng ($X^a X^a$) $\\times$ Bố mắt đỏ ($X^A Y$) $\\rightarrow F_1$: 100% cái $X^A X^a$ (đỏ) và 100% đực $X^a Y$ (trắng)."},{"id":"MCQ-MD-004","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Liên kết hoàn toàn","q":"Cho phép lai $P: \\frac{AB}{ab} \\times \\frac{Ab}{aB}$. Biết các gen liên kết hoàn toàn ở cả 2 giới và trội hoàn toàn. Tỉ lệ kiểu hình ở đời con $F_1$ là:","opts":["$3 : 1$.","$1 : 2 : 1$.","$1 : 1 : 1 : 1$.","$9 : 3 : 3 : 1$."],"ans":1,"exp":"$\\frac{AB}{ab}$ cho $(\\frac{1}{2}\\underline{AB} : \\frac{1}{2}\\underline{ab})$; $\\frac{Ab}{aB}$ cho $(\\frac{1}{2}\\underline{Ab} : \\frac{1}{2}\\underline{aB}) \\rightarrow F_1$: $1 : 2 : 1$."},{"id":"MCQ-MD-005","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Di truyền ngoài nhân","q":"Khi lai thuận và lai nghịch ở cây hoa phấn (<i>Mirabilis jalapa</i>), lấy hạt phấn của cây lá trắng thụ phấn cho hoa của cây lá xanh thuần chủng thì đời con $F_1$ có kiểu hình là:","opts":["3 cây lá xanh : 1 cây lá trắng.","100% cây lá đốm.","100% cây lá xanh.","100% cây lá trắng."],"ans":2,"exp":"Tính trạng màu lá ở cây hoa phấn do gen trong lục lạp quy định (di truyền theo dòng mẹ). Mẹ lá xanh nên 100% con $F_1$ lá xanh."},{"id":"MCQ-MD-006","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Số phép lai","q":"Một loài thực vật có 2 cặp gen $(Aa, Bb)$ phân ly độc lập. Nếu không phân biệt vai trò của cơ thể đực và cơ thể cái (lai thuận = lai nghịch), trong quần thể có tối đa bao nhiêu kiểu phép lai khác nhau?","opts":["$36$ phép lai.","$45$ phép lai.","$81$ phép lai.","$18$ phép lai."],"ans":1,"exp":"2 cặp gen PLĐL có $G = 3^2 = 9$ loại kiểu gen. Số phép lai không phân biệt giới tính $= \\frac{G(G+1)}{2} = \\frac{9 \\times 10}{2} = 45$ phép lai."},{"id":"MCQ-MD-007","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Trội không hoàn toàn","q":"Ở cây hoa phấn, alen $A$ quy định hoa đỏ trội không hoàn toàn so với alen $a$ quy định hoa trắng, kiểu gen dị hợp $Aa$ cho hoa màu hồng. Phép lai giữa hai cây hoa hồng ($Aa \\times Aa$) cho tỉ lệ kiểu hình ở đời con là:","opts":["$1$ đỏ : $2$ hồng : $1$ trắng.","$3$ đỏ : $1$ trắng.","$2$ hồng : $1$ trắng.","$100\\%$ hồng."],"ans":0,"exp":"Trội không hoàn toàn nên tỉ lệ kiểu hình trùng với tỉ lệ kiểu gen: $1 AA$ (đỏ) : $2 Aa$ (hồng) : $1 aa$ (trắng)."},{"id":"MCQ-MD-008","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hoán vị gen","q":"Ở một loài thực vật, cho cây dị hợp 2 cặp gen tự thụ phấn thu được $F_1$ có kiểu hình lặn về cả 2 tính trạng chiếm $4\\%$. Biết hoán vị gen xảy ra ở cả 2 giới với tần số như nhau. Tổng tỉ lệ các cá thể ở $F_1$ có kiểu gen đồng hợp về cả 2 cặp gen là:","opts":["$26\\%$.","$16\\%$.","$18\\%$.","$34\\%$."],"ans":0,"exp":"Ta có $\\frac{ab}{ab} = 0.04 \\Rightarrow \\underline{ab} = \\underline{AB} = 0.2$ và $\\underline{Ab} = \\underline{aB} = 0.3$. Tổng tỉ lệ đồng hợp 2 cặp $= 2(0.2)^2 + 2(0.3)^2 = 0.08 + 0.18 = 26\\%$."},{"id":"MCQ-MD-009","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tương tác + HVG","q":"Cho phép lai $P: \\frac{AB}{ab}Dd \\times \\frac{Ab}{aB}dd$, biết hoán vị gen xảy ra ở cả 2 giới với tần số $f = 20\\%$. Tỉ lệ kiểu hình mang cả 3 tính trạng trội ($A-B-D-$) ở đời con $F_1$ là:","opts":["$54\\%$.","$25.5\\%$.","$27\\%$.","$30\\%$."],"ans":2,"exp":"$\\%aabb = 0.4 \\times 0.1 = 4\\% \\Rightarrow \\%A-B- = 50\\% + 4\\% = 54\\%$. Nhân với $D- = 0.5 \\Rightarrow \\%A-B-D- = 27\\%$."},{"id":"MCQ-MD-010","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tương tác Cộng gộp","q":"Chiều cao cây do 3 cặp gen $(Aa, Bb, Dd)$ PLĐL tác động cộng gộp theo kiểu mỗi alen trội làm cây cao thêm $5\\text{ cm}$. Cây đồng hợp lặn toàn bộ ($aabbdd$) cao $100\\text{ cm}$. Cho cây dị hợp 3 cặp gen ($AaBbDd$) tự thụ phấn, tỉ lệ cây ở đời con $F_1$ có chiều cao $115\\text{ cm}$ là:","opts":["$\\frac{15}{64}$.","$\\frac{20}{64}$ ($\\frac{5}{16}$).","$\\frac{1}{64}$.","$\\frac{6}{64}$."],"ans":1,"exp":"Cây cao $115\\text{ cm}$ có $\\frac{115 - 100}{5} = 3$ alen trội. Tỉ lệ cá thể có 3 alen trội là $\\frac{C^3_6}{2^6} = \\frac{20}{64} = \\frac{5}{16}$."},{"id":"MCQ-MD-011","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tương tác Át chế","q":"Cho cây hoa trắng ($AaBb$) tự thụ phấn, đời con $F_1$ thu được tỉ lệ $13$ cây hoa trắng : $3$ cây hoa đỏ. Nếu lấy ngẫu nhiên 1 cây hoa đỏ ở $F_1$ cho tự thụ phấn thì xác suất thu được cây hoa trắng ở đời $F_2$ là:","opts":["$\\frac{2}{9}$.","$\\frac{1}{6}$.","$\\frac{1}{4}$.","$\\frac{1}{12}$."],"ans":1,"exp":"Trong các cây hoa đỏ ở $F_1$ ($1 aaBB : 2 aaBb$), cây $aaBb$ chiếm $\\frac{2}{3}$. Khi tự thụ phấn, $aaBb$ sinh ra $\\frac{1}{4}$ hoa trắng ($aabb$) $\\Rightarrow$ Xác suất $= \\frac{2}{3} \\times \\frac{1}{4} = \\frac{1}{6}$."},{"id":"MCQ-MD-012","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tế bào xảy ra HVG","q":"Trong quá trình giảm phân của một cơ thể có kiểu gen $\\frac{AB}{ab}$, người ta quan sát thấy có $30\\%$ số tế bào sinh giao tử xảy ra trao đổi chéo tại 1 điểm giữa hai gen $A$ và $B$. Tần số hoán vị gen ($f$) và tỉ lệ giao tử $\\underline{AB}$ tạo ra lần lượt là:","opts":["$f = 30\\%$ và $\\underline{AB} = 15\\%$.","$f = 30\\%$ và $\\underline{AB} = 35\\%$.","$f = 15\\%$ và $\\underline{AB} = 42.5\\%$.","$f = 15\\%$ và $\\underline{AB} = 15\\%$."],"ans":2,"exp":"$f = \\frac{30\\%}{2} = 15\\%$. Giao tử liên kết $\\underline{AB} = \\underline{ab} = 50\\% - \\frac{15\\%}{2} = 42.5\\%$."},{"id":"MCQ-MD-013","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phụ thuộc giới tính","q":"Ở người, gen $B$ nằm trên NST thường quy định tính trạng hói đầu là trội ở nam nhưng lại là lặn ở nữ ($Bb$ bị hói ở nam nhưng không hói ở nữ). Một cặp vợ chồng đều KHÔNG bị hói đầu sinh con, nhưng người chồng có bố bị hói và người vợ có mẹ bị hói. Xác suất họ sinh được một người con trai bị hói đầu là:","opts":["$\\frac{3}{8}$.","$\\frac{1}{8}$.","$\\frac{1}{2}$.","$\\frac{1}{4}$."],"ans":3,"exp":"Chồng không hói ($bb$) $\\times$ Vợ không hói có mẹ hói ($Bb$) $\\rightarrow F_1$: $\\frac{1}{2}Bb : \\frac{1}{2}bb$. Xác suất sinh con trai ($\\frac{1}{2}$) mang kiểu gen $Bb$ ($\\frac{1}{2}$) $= \\frac{1}{4}$."},{"id":"MCQ-MD-014","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Gen gây chết","q":"Ở cá kiếm, alen $A$ quy định vảy sọc trội hoàn toàn so với $a$ quy định vảy trơn, nhưng kiểu gen đồng hợp trội $AA$ gây chết ở giai đoạn phôi; alen $B$ quy định đuôi dài trội hoàn toàn so với $b$ quy định đuôi ngắn (phân ly độc lập và không gây chết). Phép lai giữa hai cá thể cá kiếm vảy sọc, đuôi dài dị hợp ($AaBb \\times AaBb$) sẽ cho tỉ lệ kiểu hình ở các cá thể sống sót đời $F_1$ là:","opts":["$3 : 3 : 1 : 1$.","$4 : 2 : 2 : 1$.","$9 : 3 : 3 : 1$.","$6 : 2 : 3 : 1$."],"ans":3,"exp":"Cặp $Aa \\times Aa$ có $AA$ chết nên tỉ lệ sống sót là $(2\\text{ sọc} : 1\\text{ trơn})$. Cặp $Bb \\times Bb$ cho $(3\\text{ dài} : 1\\text{ ngắn})$. Tích 2 tính trạng $= (2:1)(3:1) = 6 : 2 : 3 : 1$."},{"id":"MCQ-MD-015","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Số kiểu gen tối đa - Đề HSG Tỉnh","q":"Ở một loài động vật ($XX, XY$), xét Lôcut 1 có 3 alen trên NST thường; Lôcut 2 có 2 alen và Lôcut 3 có 3 alen cùng nằm trên vùng tương đồng của $X$ và $Y$. Số loại kiểu gen tối đa trong quần thể là:","opts":["$342$ kiểu gen.","$162$ kiểu gen.","$324$ kiểu gen.","$216$ kiểu gen."],"ans":0,"exp":"NST thường: $\\frac{3 \\times 4}{2} = 6$. Trên $XY$ ($G = 2 \\times 3 = 6$): Giới $XX$ có $\\frac{6 \\times 7}{2} = 21$, giới $XY$ có $6^2 = 36 \\Rightarrow 6 \\times (21 + 36) = 342$."},{"id":"MCQ-MD-016","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Thử nghiệm bổ sung Cis-Trans - Đề HSG Tỉnh","q":"Phân lập 4 dòng nấm men đột biến lặn khuyết dưỡng Adenine ($1, 2, 3, 4$). Kết quả lai: $(1 \\times 3)$ và $(2 \\times 4)$ mọc bình thường (+); $(1 \\times 4)$ và $(2 \\times 3)$ không mọc được (-). Bốn dòng này thuộc bao nhiêu gen khác nhau?","opts":["2 gen (Nhóm I: 1, 4; Nhóm II: 2, 3).","3 gen.","1 gen.","4 gen."],"ans":0,"exp":"Hai dòng lai với nhau cho (-) thì thuộc cùng 1 gen $\\Rightarrow$ (1, 4) thuộc Gen I và (2, 3) thuộc Gen II."},{"id":"MCQ-MD-017","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bản đồ 3 điểm & Nhiễu - Đề HSG Tỉnh","q":"Ở ruồi giấm, 3 gen liên kết theo thứ tự $A - B - D$ với khoảng cách $d(A-B) = 10\\text{ cM}$ và $d(B-D) = 20\\text{ cM}$. Nếu hệ số trùng hợp $C = 0.6$ (tức độ nhiễu $I = 0.4$), khi lai phân tích ruồi cái $\\frac{AbD}{aBd} \\times \\frac{abd}{abd}$ thì tỉ lệ cá thể có kiểu hình đồng hợp lặn cả 3 tính trạng ($\\frac{abd}{abd}$) ở đời con là:","opts":["$5.0\\%$.","$4.4\\%$.","$9.4\\%$.","$0.6\\%$."],"ans":1,"exp":"Giao tử $\\underline{abd}$ từ mẹ $\\frac{AbD}{aBd}$ là giao tử TĐC đơn ở vùng I ($A-B$). Ta có $f_{\\text{kép}} = 0.6 \\times 0.1 \\times 0.2 = 1.2\\% \\Rightarrow f_{\\text{đơn I}} = 10\\% - 1.2\\% = 8.8\\% \\Rightarrow \\%\\underline{abd} = \\frac{8.8\\%}{2} = 4.4\\%$."},{"id":"MCQ-MD-018","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bản đồ Tâm động Neurospora - Đề HSG Tỉnh","q":"Ở nấm <i>Neurospora crassa</i>, lai chủng kiểu dại ($arg^+$) với chủng đột biến ($arg^-$). Trong 500 nang bào tử được kiểm tra, có 420 nang có kiểu sắp xếp bào tử dạng $4:4$ (FDS) và 80 nang có kiểu sắp xếp $2:2:2:2$ hoặc $2:4:2$ (SDS). Khoảng cách từ gen $arg$ đến tâm động là:","opts":["$8\\text{ cM}$.","$16\\text{ cM}$.","$4\\text{ cM}$.","$84\\text{ cM}$."],"ans":0,"exp":"$d(\\text{Gen} - \\text{Tâm động}) = \\frac{1}{2} \\times \\frac{80}{500} \\times 100 = 8\\text{ cM}$."},{"id":"MCQ-MD-019","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Con đường Hóa sinh & Tương tác - Đề HSG Tỉnh","q":"Chuỗi tổng hợp sắc tố hoa: Chất tiền thân (trắng) $\\xrightarrow{\\text{Enzyme A}}$ Sắc tố vàng $\\xrightarrow{\\text{Enzyme B}}$ Sắc tố đỏ. Alen trội $D$ (PLĐL với $A, B$) ức chế hoàn toàn hoạt tính của Enzyme B (alen $d$ không ức chế). Cho cây $AaBbDd$ tự thụ phấn, tỉ lệ kiểu hình (Trắng : Vàng : Đỏ) ở $F_1$ là:","opts":["$28$ Trắng : $27$ Vàng : $9$ Đỏ.","$16$ Trắng : $21$ Vàng : $27$ Đỏ.","$16$ Trắng : $39$ Vàng : $9$ Đỏ.","$12$ Trắng : $3$ Vàng : $1$ Đỏ."],"ans":2,"exp":"Trắng ($aa-- --$) $= \\frac{16}{64}$; Đỏ ($A-B-dd$) $= \\frac{3}{4} \\times \\frac{3}{4} \\times \\frac{1}{4} = \\frac{9}{64}$; Vàng $= 1 - \\frac{25}{64} = \\frac{39}{64}$."},{"id":"MCQ-MD-020","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hiệu ứng Dòng mẹ - Đề HSG Tỉnh","q":"Ở ốc <i>Limnaea peregra</i>, alen $D$ (xoắn phải) trội hoàn toàn so với $d$ (xoắn trái) và di truyền theo hiệu ứng dòng mẹ. Lấy một con ốc có kiểu gen $dd$ (nhưng vỏ xoắn phải do mẹ nó là $Dd$) cho tự thụ tinh thì đời con $F_1$ và đời cháu $F_2$ có kiểu hình như thế nào?","opts":["$F_1$: 100% xoắn phải; $F_2$: 3 xoắn phải : 1 xoắn trái.","$F_1$: 100% xoắn trái; $F_2$: 100% xoắn trái.","$F_1$: 100% xoắn phải; $F_2$: 100% xoắn trái.","$F_1$: 3 xoắn phải : 1 xoắn trái; $F_2$: 100% xoắn trái."],"ans":1,"exp":"Mẹ đem tự thụ có kiểu gen $dd$ nên cả $F_1$ và $F_2$ đều biểu hiện 100% xoắn trái theo kiểu gen của mẹ."},{"id":"MCQ-MD-021","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Kiểm định Chi-square ($\\chi^2$) trong Di truyền - Đề HSG Tỉnh","q":"Khi lai phân tích một cơ thể dị hợp 2 cặp gen $(Aa, Bb)$, một học sinh giả thuyết rằng 2 cặp gen này phân ly độc lập (tỉ lệ kỳ vọng $1:1:1:1$) và thu được kết quả thực nghiệm trên $400$ cá thể đời con gồm: $120$ cá thể kiểu hình 1 : $120$ cá thể kiểu hình 2 : $80$ cá thể kiểu hình 3 : $80$ cá thể kiểu hình 4. Giá trị $\\chi^2 = \\sum \\frac{(O - E)^2}{E}$ của phép thử này là bao nhiêu (cho biết ngưỡng $\\chi^2_{0.05; df=3} = 7.815$)?","opts":["$\\chi^2 = 16 > 7.815 \\Rightarrow$ Bác bỏ giả thuyết phân ly độc lập (2 gen có liên kết).","$\\chi^2 = 4 < 7.815 \\Rightarrow$ Chấp nhận giả thuyết phân ly độc lập.","$\\chi^2 = 1.6 < 7.815 \\Rightarrow$ Chấp nhận giả thuyết.","$\\chi^2 = 8 > 7.815 \\Rightarrow$ Bác bỏ giả thuyết."],"ans":0,"exp":"Số cá thể kỳ vọng ở mỗi lớp là $E = \\frac{400}{4} = 100$. Ta có $\\chi^2 = \\frac{(120-100)^2}{100} + \\frac{(120-100)^2}{100} + \\frac{(80-100)^2}{100} + \\frac{(80-100)^2}{100} = 4 + 4 + 4 + 4 = 16 > 7.815 \\Rightarrow$ Bác bỏ giả thuyết PLĐL."},{"id":"MCQ-MD-022","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Độ thấm (Penetrance) của Gen - Đề HSG Tỉnh","q":"Ở người, một bệnh di truyền do alen trội $A$ trên NST thường quy định, nhưng alen này có độ thấm (penetrance) chỉ đạt $80\\%$ (tức là trong số những người mang kiểu gen $AA$ hoặc $Aa$, chỉ có $80\\%$ biểu hiện thành kiểu hình bệnh, còn $20\\%$ vẫn có kiểu hình bình thường). Một người đàn ông có kiểu gen dị hợp $Aa$ kết hôn với người phụ nữ bình thường $aa$. Xác suất để đứa con đầu lòng của họ biểu hiện kiểu hình mắc bệnh là:","opts":["$50\\%$.","$20\\%$.","$40\\%$.","$80\\%$."],"ans":2,"exp":"Phép lai $Aa \\times aa$ tạo ra xác suất con mang kiểu gen $Aa$ là $50\\% = 0.5$. Vì độ thấm của kiểu gen $Aa$ là $80\\% = 0.8$, nên xác suất đứa con biểu hiện kiểu hình bệnh là $0.5 \\times 0.8 = 0.40 = 40\\%$."},{"id":"MCQ-MD-023","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quy luật Phân ly","q":"Cơ sở tế bào học của quy luật phân ly do Gregor Mendel phát hiện trên cây đậu Hà Lan là gì?","opts":["Sự trao đổi chéo giữa các nhiễm sắc thể không tương đồng ở kỳ đầu I.","Sự nhân đôi độc lập của các plasmid trong tế bào chất.","Sự phân ly đồng đều của cặp nhiễm sắc thể tương đồng mang cặp alen tương ứng trong giảm phân tạo giao tử và sự tổ hợp ngẫu nhiên trong thụ tinh.","Sự di truyền thẳng qua nhiễm sắc thể Y."],"ans":2,"exp":"Mỗi tính trạng do một cặp nhân tố di truyền (cặp alen) nằm trên cặp NST tương đồng quy định; khi giảm phân, 2 alen phân ly về 2 giao tử khác nhau."},{"id":"MCQ-MD-024","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quy luật Phân ly","q":"Trong phép lai phân tích một cơ thể mang kiểu hình trội về 1 cặp gen ($A-$) với cơ thể đồng hợp lặn ($aa$), nếu đời con $F_a$ thu được đồng tính $100\\%$ mang kiểu hình trội thì cơ thể trội ban đầu có kiểu gen là:","opts":["Hoặc $AA$ hoặc $Aa$ đều cho kết quả như nhau.","Đồng hợp lặn ($aa$).","Dị hợp ($Aa$).","Đồng hợp trội ($AA$)."],"ans":3,"exp":"Phép lai phân tích kiểm tra kiểu gen của cá thể trội: nếu $AA \\times aa \\rightarrow 100\\% Aa$ (đồng tính trội); nếu $Aa \\times aa \\rightarrow 1:1$ (phân tính)."},{"id":"MCQ-MD-025","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phân ly độc lập","q":"Điều kiện nghiệm đúng cốt lõi nhất để hai cặp gen quy định hai tính trạng khác nhau di truyền theo quy luật phân ly độc lập của Mendel là:","opts":["Cơ thể bố mẹ phải là dòng thuần chủng $100\\%$.","Hai cặp gen phải nằm trên hai cặp nhiễm sắc thể tương đồng khác nhau.","Hai cặp gen phải nằm rất gần nhau trên cùng một nhiễm sắc thể.","Một alen phải trội không hoàn toàn so với alen kia."],"ans":1,"exp":"Phân ly độc lập xảy ra khi các cặp gen nằm trên các cặp NST tương đồng khác nhau, giúp các cặp alen phân ly độc lập về giao tử ở kỳ sau giảm phân I."},{"id":"MCQ-MD-026","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phân ly độc lập","q":"Cho phép lai $P: AaBbDd \\times aaBbdd$ (các cặp gen phân ly độc lập, trội hoàn toàn). Số loại kiểu gen và số loại kiểu hình tối đa thu được ở đời con $F_1$ lần lượt là:","opts":["$18$ kiểu gen và $4$ kiểu hình.","$12$ kiểu gen và $8$ kiểu hình.","$12$ kiểu gen và $4$ kiểu hình.","$8$ kiểu gen và $8$ kiểu hình."],"ans":1,"exp":"Xét từng cặp: $Aa \\times aa \\rightarrow 2\\text{ KG}, 2\\text{ KH}$; $Bb \\times Bb \\rightarrow 3\\text{ KG}, 2\\text{ KH}$; $Dd \\times dd \\rightarrow 2\\text{ KG}, 2\\text{ KH}$. Tổng $= 2 \\times 3 \\times 2 = 12$ KG và $2 \\times 2 \\times 2 = 8$ KH."},{"id":"MCQ-MD-027","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phân ly độc lập","q":"Một cơ thể thực vật có kiểu gen $AaBbDdEe$ tự thụ phấn (các gen phân ly độc lập, trội hoàn toàn). Tỉ lệ cá thể ở $F_1$ có kiểu gen giống bố mẹ ($AaBbDdEe$) là bao nhiêu?","opts":["$\\frac{1}{8}$.","$\\frac{1}{256}$.","$\\frac{81}{256}$.","$\\frac{1}{16}$."],"ans":3,"exp":"Mỗi cặp $Aa \\times Aa$ cho $\\frac{1}{2} Aa$. Với $4$ cặp dị hợp độc lập: $(\\frac{1}{2})^4 = \\frac{1}{16}$."},{"id":"MCQ-MD-028","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phân ly độc lập","q":"Trong phép lai giữa hai cây đậu Hà Lan dị hợp 2 cặp gen hạt vàng trơn ($AaBb \\times AaBb$), nếu thu được $3200$ hạt ở đời $F_1$ thì theo lý thuyết có khoảng bao nhiêu hạt mang kiểu hình vàng nhăn ($A-bb$)?","opts":["$200$ hạt.","$1800$ hạt.","$600$ hạt.","$800$ hạt."],"ans":2,"exp":"Tỉ lệ $A-bb = \\frac{3}{4} \\times \\frac{1}{4} = \\frac{3}{16}$. Số hạt vàng nhăn $= 3200 \\times \\frac{3}{16} = 600$ hạt."},{"id":"MCQ-MD-029","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Trội không hoàn toàn & Đồng trội","q":"Ở người, nhóm máu hệ MN do hai alen đồng trội $L^M$ và $L^N$ quy định ($L^M L^M$ nhóm M, $L^M L^N$ nhóm MN, $L^N L^N$ nhóm N). Nếu người bố có nhóm máu MN kết hôn với người mẹ cũng có nhóm máu MN, tỉ lệ kiểu hình nhóm máu ở các con của họ là:","opts":["$1$ nhóm M : $2$ nhóm MN : $1$ nhóm N.","$100\\%$ nhóm MN.","$1$ nhóm M : $1$ nhóm N.","$3$ nhóm M : $1$ nhóm N."],"ans":0,"exp":"Cả hai bố mẹ đều dị hợp $L^M L^N \\times L^M L^N \\rightarrow 1\\text{ }L^M L^M\\text{ (M)} : 2\\text{ }L^M L^N\\text{ (MN)} : 1\\text{ }L^N L^N\\text{ (N)}$."},{"id":"MCQ-MD-030","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhóm máu ABO","q":"Ở người, một cặp vợ chồng có người chồng nhóm máu A ($I^A I^O$) và người vợ nhóm máu B ($I^B I^O$). Đứa con đầu lòng của họ có thể có tối đa bao nhiêu loại kiểu hình nhóm máu khác nhau?","opts":["Chỉ có nhóm máu A, B hoặc AB (không thể sinh con nhóm máu O).","Chỉ có duy nhất nhóm máu AB.","Chỉ có nhóm máu A hoặc nhóm máu B.","Cả $4$ loại nhóm máu (A, B, AB, O) với xác suất bằng nhau $\\frac{1}{4}$ mỗi loại."],"ans":3,"exp":"Phép lai $I^A I^O \\times I^B I^O$ sinh ra 4 tổ hợp bằng nhau: $\\frac{1}{4} I^A I^B$ (AB), $\\frac{1}{4} I^A I^O$ (A), $\\frac{1}{4} I^B I^O$ (B), $\\frac{1}{4} I^O I^O$ (O)."},{"id":"MCQ-MD-031","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tương tác bổ sung","q":"Ở cây đậu thơm, màu hoa do 2 cặp gen không alen $A/a$ và $B/b$ phân ly độc lập tương tác bổ sung: có đồng thời cả hai alen trội ($A-B-$) cho hoa đỏ, thiếu một trong hai hoặc cả hai ($A-bb, aaB-, aabb$) cho hoa trắng. Phép lai $P: AAbb \\times aaBB$ cho đời $F_1$ và $F_2$ (khi $F_1$ tự thụ) có tỉ lệ kiểu hình lần lượt là:","opts":["$F_1$: $100\\%$ hoa trắng; $F_2$: $3$ hoa đỏ : $1$ hoa trắng.","$F_1$: $1$ đỏ : $1$ trắng; $F_2$: $9$ đỏ : $6$ hồng : $1$ trắng.","$F_1$: $100\\%$ hoa đỏ; $F_2$: $15$ đỏ : $1$ trắng.","$F_1$: $100\\%$ hoa đỏ; $F_2$: $9$ hoa đỏ : $7$ hoa trắng."],"ans":3,"exp":"Hai dòng trắng thuần chủng $AAbb \\times aaBB \\rightarrow F_1: 100\\% AaBb$ (hoa đỏ do có đủ cả A và B). $F_1$ tự thụ cho $F_2$ gồm $9/16\\text{ }A-B-$ (đỏ) : $7/16$ còn lại (trắng)."},{"id":"MCQ-MD-032","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tương tác cộng gộp","q":"Tính trạng màu da người hay chiều cao ở nhiều loài thực vật thường do nhiều cặp gen không alen cùng tác động, mỗi alen trội đóng góp một lượng nhỏ tương đương vào sự phát triển tính trạng (tạo dải biến dị liên tục). Đây là kiểu tương tác gen nào?","opts":["Tương tác bổ sung $9:7$.","Tương tác cộng gộp (Polygenic inheritance).","Hiện tượng gen đa hiệu.","Tương tác át chế trội $12:3:1$."],"ans":1,"exp":"Các tính trạng số lượng (chiều cao, cân nặng, màu da, sản lượng sữa/hạt) thường chịu sự chi phối của nhiều gen cộng gộp kết hợp ảnh hưởng của môi trường."},{"id":"MCQ-MD-033","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Gen đa hiệu","q":"Một gen duy nhất nhưng sản phẩm của nó có thể đồng thời tác động ảnh hưởng tới sự biểu hiện của nhiều tính trạng khác nhau trong cơ thể (ví dụ ở đậu Hà Lan, alen quy định hoa tím luôn làm hạt màu nâu và xuất hiện chấm đen ở nách lá) gọi là hiện tượng gì?","opts":["Hoán vị gen.","Di truyền ngoài nhân.","Tác động đa hiệu của gen (Pleiotropy).","Tương tác cộng gộp nhiều gen."],"ans":2,"exp":"Gen đa hiệu (1 gen $\\rightarrow$ nhiều tính trạng) rất phổ biến vì một protein enzyme/cấu trúc thường tham gia nhiều quá trình sinh lý ở các mô khác nhau (ví dụ bệnh hồng cầu hình liềm $Hb^S$, hội chứng Marfan)."},{"id":"MCQ-MD-034","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Liên kết gen hoàn toàn","q":"Hiện tượng các gen nằm trên cùng một nhiễm sắc thể thường di truyền cùng nhau trong giảm phân và thụ tinh gọi là liên kết gen. Cơ sở tế bào học của liên kết gen hoàn toàn là gì?","opts":["Luôn xảy ra trao đổi chéo giữa hai chromatid chị em.","Các gen nằm trên các NST khác nhau nhưng hút nhau về một cực.","Các gen chuyển từ nhân ra ti thể.","Các gen nằm trên cùng một NST phân ly cùng nhau về giao tử và KHÔNG xảy ra trao đổi chéo giữa các gen đó."],"ans":3,"exp":"Mỗi nhiễm sắc thể là một nhóm gen liên kết; số nhóm gen liên kết thường bằng số lượng NST trong bộ đơn bội $n$ của loài."},{"id":"MCQ-MD-035","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Liên kết gen hoàn toàn","q":"Ở một loài thực vật có bộ NST $2n = 24$. Số nhóm gen liên kết tối đa của loài này (xét các gen trên NST thường) là bao nhiêu?","opts":["$48$ nhóm.","$12$ nhóm.","$6$ nhóm.","$24$ nhóm."],"ans":1,"exp":"Số nhóm gen liên kết ở sinh vật lưỡng bội bằng số NST đơn bội $n = 24/2 = 12$ nhóm."},{"id":"MCQ-MD-036","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hoán vị gen","q":"Khoảng cách tương đối giữa hai gen liên kết trên cùng một nhiễm sắc thể được đo bằng đơn vị bản đồ (cM). Nếu tần số hoán vị gen giữa gen $A$ và gen $B$ đo được là $18\\%$, khoảng cách bản đồ giữa chúng là bao nhiêu?","opts":["$9\\text{ cM}$.","$82\\text{ cM}$.","$36\\text{ cM}$.","$18\\text{ cM}$ (18 đơn vị bản đồ)."],"ans":3,"exp":"Theo quy ước của Alfred Sturtevant, $1\\%$ tần số hoán vị gen (tái tổ hợp) tương ứng với $1\\text{ cM}$ (centiMorgan), nên $f = 18\\%$ ứng với $18\\text{ cM}$."},{"id":"MCQ-MD-037","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hoán vị gen","q":"Ở cơ thể có kiểu gen $\\frac{Ab}{aB}$, khi giảm phân có xảy ra hoán vị gen với tần số $f = 24\\%$. Tỉ lệ phần trăm từng loại giao tử tạo thành lần lượt là:","opts":["$\\underline{AB} = \\underline{ab} = 38\\%$ và $\\underline{Ab} = \\underline{aB} = 12\\%$.","$\\underline{Ab} = \\underline{aB} = 44\\%$ và $\\underline{AB} = \\underline{ab} = 6\\%$.","$\\underline{Ab} = \\underline{aB} = 26\\%$ và $\\underline{AB} = \\underline{ab} = 24\\%$.","$\\underline{Ab} = \\underline{aB} = 38\\%$ và $\\underline{AB} = \\underline{ab} = 12\\%$."],"ans":3,"exp":"Với dị hợp chéo $\\frac{Ab}{aB}$, giao tử liên kết là $\\underline{Ab} = \\underline{aB} = 50\\% - \\frac{24\\%}{2} = 38\\%$; giao tử hoán vị là $\\underline{AB} = \\underline{ab} = \\frac{24\\%}{2} = 12\\%$."},{"id":"MCQ-MD-038","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hoán vị gen","q":"Tần số hoán vị gen giữa hai gen bất kỳ nằm trên cùng một nhiễm sắc thể KHÔNG bao giờ vượt quá ngưỡng giá trị nào trong điều kiện bình thường?","opts":["$25\\%$.","$50\\%$.","$75\\%$.","$100\\%$."],"ans":1,"exp":"Vì trao đổi chéo chỉ diễn ra giữa 2 trong 4 chromatid của cặp tương đồng ở kỳ đầu I (tối đa $50\\%$ sản phẩm là tái tổ hợp ngay cả khi $100\\%$ tế bào đều có trao đổi chéo), nên $f \\le 50\\%$."},{"id":"MCQ-MD-039","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hoán vị gen","q":"Ý nghĩa tiến hóa và chọn giống quan trọng nhất của hiện tượng hoán vị gen là gì?","opts":["Tăng nguồn biến dị tổ hợp, tạo điều kiện cho các gen quý nằm trên các NST khác nhau có thể tái tổ hợp lại vào cùng một NST (tạo nhóm gen liên kết quý mới).","Giúp cố định tuyệt đối mọi tính trạng xấu lẫn tốt thành một khối không thể tách rời.","Làm tăng số lượng nhiễm sắc thể của loài lên $4n$.","Ngăn cản sự phát sinh đột biến điểm."],"ans":0,"exp":"Hoán vị gen phá vỡ sự liên kết cứng nhắc, giúp ghép các alen có lợi từ các cá thể khác nhau lên cùng 1 NST để chọn lọc tự nhiên hoặc nhà chọn giống giữ lại."},{"id":"MCQ-MD-040","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Liên kết giới tính","q":"Ở các loài chim, bướm và một số loài bò sát, cá, cặp nhiễm sắc thể giới tính quy định con đực và con cái theo cơ chế nào?","opts":["Con đực mang $XY$; con cái mang $XX$.","Con đực mang cặp đồng giao tử $ZZ$; con cái mang cặp dị giao tử $ZW$.","Con đực mang $XO$; con cái mang $XX$.","Con đực đơn bội $n$; con cái lưỡng bội $2n$."],"ans":1,"exp":"Hệ $ZZ/ZW$ (ở chim, gà, bướm, dâu tây): con đực đồng giao tử $ZZ$, con cái dị giao tử $ZW$ (trứng quyết định giới tính con)."},{"id":"MCQ-MD-041","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Liên kết giới tính","q":"Ở loài ong mật (và kiến, ong bắp cày), cơ chế xác định giới tính đặc biệt nào làm cho con ong đực luôn truyền $100\\%$ hệ gen của mình cho các con ong cái đời sau và không có bố?","opts":["Cơ chế $XX/XY$ giống động vật có vú.","Cơ chế Đơn bội - Lưỡng bội (Arrhenotoky): trứng không thụ tinh phát triển thành ong đực đơn bội ($n$); trứng thụ tinh phát triển thành ong cái ($2n$).","Cơ chế phụ thuộc nhiệt độ ấp trứng.","Cơ chế $ZZ/ZW$."],"ans":1,"exp":"Ong đực phát triển trinh sinh từ trứng chưa thụ tinh ($n = 16$) nên sinh tinh bằng nguyên phân cho $100\\%$ tinh trùng giống hệt mình."},{"id":"MCQ-MD-042","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Liên kết giới tính","q":"Ở người, bệnh máu khó đông (Hemophilia A) do gen lặn $h$ nằm trên vùng không tương đồng của nhiễm sắc thể giới tính X quy định (alen $H$ bình thường trội hoàn toàn). Một cặp vợ chồng đều KHÔNG mắc bệnh này ($X^H X^h \\times X^H Y$) sinh con. Xác suất sinh được một đứa con trai bị bệnh máu khó đông là bao nhiêu?","opts":["$12.5\\%$ ($\\frac{1}{8}$).","$0\\%$.","$25\\%$ ($\\frac{1}{4}$).","$50\\%$ ($\\frac{1}{2}$)."],"ans":2,"exp":"Phép lai $X^H X^h \\times X^H Y \\rightarrow \\frac{1}{4} X^H X^H : \\frac{1}{4} X^H X^h : \\frac{1}{4} X^H Y : \\frac{1}{4} X^h Y$. Con trai mắc bệnh ($X^h Y$) chiếm $\\frac{1}{4} = 25\\%$ tổng số con (hoặc $50\\%$ trong số các con trai)."},{"id":"MCQ-MD-043","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Liên kết giới tính","q":"Bố mắc bệnh di truyền hiếm gặp (tật có túm lông ở vành tai hoặc tật dính ngón tay $2-3$) truyền tính trạng đó cho $100\\%$ con trai, không bao giờ truyền cho con gái, và các con trai lại truyền tiếp cho $100\\%$ cháu trai. Gen quy định tật này nằm ở đâu?","opts":["Trên vùng không tương đồng của nhiễm sắc thể giới tính Y (di truyền thẳng theo dòng bố).","Trên nhiễm sắc thể thường số 1.","Trên vùng không tương đồng của nhiễm sắc thể X.","Trong DNA ti thể."],"ans":0,"exp":"Chỉ có nam giới mang NST Y và truyền nguyên vẹn vùng không tương đồng của Y từ bố sang con trai — gọi là di truyền thẳng theo giới tính."},{"id":"MCQ-MD-044","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Liên kết giới tính","q":"Ở gà, alen $B$ quy định lông vằn trội hoàn toàn so với alen $b$ quy định lông đen nằm trên vùng không tương đồng của NST Z (không có trên W). Trong chăn nuôi gà con mới nở, người ta muốn dùng phép lai phân biệt nhanh gà trống và gà mái ngay khi mới nở qua màu lông. Cặp bố mẹ nào phù hợp?","opts":["Gà trống lông đen ($Z^b Z^b$) $\\times$ Gà mái lông đen ($Z^b W$).","Gà trống lông vằn ($Z^B Z^B$) $\\times$ Gà mái lông đen ($Z^b W$).","Gà trống lông đen ($Z^b Z^b$) $\\times$ Gà mái lông vằn ($Z^B W$).","Gà trống lông vằn ($Z^B Z^b$) $\\times$ Gà mái lông vằn ($Z^B W$)."],"ans":2,"exp":"Khi lai trống đen ($Z^b Z^b$) $\\times$ mái vằn ($Z^B W$): $100\\%$ con trống là $Z^B Z^b$ (lông vằn, có đốm trắng trên đầu lúc mới nở), $100\\%$ con mái là $Z^b W$ (lông đen tuyền) — tách giới tính chính xác $100\\%$!"},{"id":"MCQ-MD-045","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Di truyền ngoài nhân","q":"Năm 1909, Carl Correns thực hiện thí nghiệm lai thuận và lai nghịch ở cây hoa phấn (<i>Mirabilis jalapa</i>) về màu sắc lá (xanh, trắng, đốm) và phát hiện đời con luôn có kiểu hình giống cây mẹ. Đặc điểm di truyền cốt lõi của các gen nằm trong tế bào chất (lục lạp, ti thể) là gì?","opts":["Chỉ biểu hiện ở cá thể đực mà không biểu hiện ở cá thể cái.","Các gen trong ty thể luôn nằm thành cặp alen tương đồng như trong nhân.","Không phân ly theo tỉ lệ chuẩn xác của Mendel và đời con biểu hiện kiểu hình giống mẹ do giao tử đực hầu như chỉ truyền nhân, còn tế bào chất hợp tử nhận chủ yếu từ trứng mẹ.","Khi lai thuận và lai nghịch luôn cho kết quả $3:1$ ở $F_2$."],"ans":2,"exp":"Hạt phấn thực vật và tinh trùng động vật chứa lượng tế bào chất cực nhỏ (và ti thể của tinh trùng thường bị phân hủy sau thụ tinh), nên DNA lục lạp và ti thể di truyền theo dòng mẹ."},{"id":"MCQ-MD-046","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Di truyền ngoài nhân","q":"Ở người, bệnh teo thần kinh thị giác di truyền Leber (LHON) gây suy giảm thị lực do một đột biến điểm ở gen nằm trên DNA ti thể. Một người đàn ông bị bệnh LHON kết hôn với một người phụ nữ bình thường (mang $100\\%$ ti thể lành). Xác suất đứa con đầu lòng của họ thừa hưởng alen bệnh từ bố là bao nhiêu?","opts":["$100\\%$ nếu sinh con gái.","$25\\%$ cho mọi đứa con.","$50\\%$ nếu sinh con trai.","Gần như bằng $0\\%$ (bệnh ti thể chỉ di truyền từ mẹ, bố bị bệnh không truyền cho con)."],"ans":3,"exp":"Ti thể trong hợp tử có nguồn gốc từ tế bào trứng của mẹ; người bố mắc bệnh ti thể không truyền gen ti thể cho cả con trai lẫn con gái."},{"id":"MCQ-MD-047","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Thường biến & Mức phản ứng","q":"Cây hoa Cẩm tú cầu (<i>Hydrangea macrophylla</i>) có cùng một kiểu gen nhưng khi trồng ở đất chua ($pH < 5.5$) cho hoa màu xanh lam, còn trồng ở đất kiềm ($pH > 7.0$) lại cho hoa màu hồng/đỏ. Hiện tượng này minh họa cho khái niệm nào?","opts":["Di truyền qua tế bào chất.","Đột biến cấu trúc nhiễm sắc thể do pH đất.","Đột biến điểm trên gen tổng hợp sắc tố anthocyanin.","Thường biến (sự biến đổi kiểu hình của cùng một kiểu gen trước sự thay đổi của điều kiện môi trường, không di truyền cho đời sau)."],"ans":3,"exp":"pH đất làm thay đổi khả năng hấp thụ ion nhôm ($\\text{Al}^{3+}$) của rễ, từ đó biến đổi phức hợp màu sắc tố cánh hoa — một thường biến điển hình nằm trong giới hạn mức phản ứng của kiểu gen."},{"id":"MCQ-MD-048","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Thường biến & Mức phản ứng","q":"Tập hợp tất cả các kiểu hình có thể có của cùng một kiểu gen tương ứng với các điều kiện môi trường khác nhau được gọi là gì, và yếu tố nào quyết định giới hạn đó?","opts":["Thể đột biến; do môi trường tự do quyết định hoàn toàn.","Mức phản ứng; giới hạn của mức phản ứng do KIỂU GEN quy định và có khả năng di truyền.","Biến dị tổ hợp; do trao đổi chéo quyết định.","Độ thẩm; do số lượng ti thể quyết định."],"ans":1,"exp":"Mức phản ứng là thuộc tính di truyền của kiểu gen (tính trạng chất lượng thường có mức phản ứng hẹp, tính trạng số lượng/năng suất có mức phản ứng rộng)."},{"id":"MCQ-MD-049","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Mức phản ứng & Chọn giống","q":"Để xác định chính xác mức phản ứng của một kiểu gen ở một giống cây trồng (ví dụ cây hoa hồng hoặc cây mía), phương pháp khoa học đúng đắn nhất là gì?","opts":["Xử lý hóa chất phóng xạ gây đột biến hạt phấn.","Lai xa giữa hai loài khác nhau.","Nhân giống vô tính (giâm cành, nuôi cấy mô) tạo nhiều cây con có CÙNG KIỂU GEN giống hệt nhau rồi đem trồng trong nhiều môi trường khác nhau để theo dõi kiểu hình.","Cho các cây giao phấn tự do với nhiều giống khác rồi trồng cùng 1 mảnh ruộng."],"ans":2,"exp":"Muốn khảo sát mức phản ứng của 1 kiểu gen bắt buộc phải tạo được các cá thể đồng nhất kiểu gen (bằng nhân giống vô tính ở cây hoặc dòng thuần chủng, sinh đôi cùng trứng) và đặt vào nhiều môi trường khác nhau."},{"id":"MCQ-MD-050","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Số kiểu gen","q":"Xét một gen nằm trên nhiễm sắc thể thường có $4$ alen khác nhau ($a_1, a_2, a_3, a_4$). Trong quần thể lưỡng bội, số loại kiểu gen tối đa có thể hình thành từ gen này gồm bao nhiêu kiểu gen đồng hợp và bao nhiêu kiểu gen dị hợp?","opts":["$4$ kiểu gen đồng hợp và $12$ kiểu gen dị hợp (tổng $16$ kiểu gen).","$4$ kiểu gen đồng hợp và $4$ kiểu gen dị hợp.","$4$ kiểu gen đồng hợp và $6$ kiểu gen dị hợp (tổng $10$ kiểu gen).","$6$ kiểu gen đồng hợp và $4$ kiểu gen dị hợp."],"ans":2,"exp":"Với $r = 4$ alen: số KG đồng hợp $= r = 4$; số KG dị hợp $= C^2_4 = 6$; tổng số KG $= \\frac{r(r+1)}{2} = 10$."},{"id":"MCQ-MD-051","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tổ hợp Mendel","q":"Trong phép lai $P: AaBbDd \\times AaBbDd$ (trội hoàn toàn, PLĐL). Tỉ lệ kiểu hình ở đời $F_1$ mang ĐÚNG $2$ tính trạng trội và $1$ tính trạng lặn là bao nhiêu?","opts":["$\\frac{27}{32}$.","$\\frac{27}{64}$.","$\\frac{1}{64}$.","$\\frac{9}{64}$."],"ans":1,"exp":"Áp dụng công thức tổ hợp: $C^2_3 \\times (\\frac{3}{4})^2 \\times (\\frac{1}{4})^1 = 3 \\times \\frac{9}{16} \\times \\frac{1}{4} = \\frac{27}{64}$."},{"id":"MCQ-MD-052","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tương tác Át chế","q":"Ở một loài chó săn Labrador, màu lông do 2 cặp gen PLĐL: alen $B$ (lông đen) trội hoàn toàn so với $b$ (lông nâu); alen $E$ cho phép tích lũy sắc tố vào lông, còn đồng hợp lặn $ee$ át chế không cho sắc tố vào lông khiến lông có màu vàng bất kể $B$ hay $b$. Cho hai con chó dị hợp 2 cặp gen ($BbEe \\times BbEe$) giao phối với nhau, tỉ lệ màu lông ở đàn con là:","opts":["$9$ lông đen : $7$ lông vàng.","$9$ lông đen : $3$ lông nâu : $4$ lông vàng.","$13$ lông vàng : $3$ lông đen.","$12$ lông đen : $3$ lông nâu : $1$ lông vàng."],"ans":1,"exp":"Át chế lặn ($9:3:4$): $B-E-$ ($\\frac{9}{16}$) lông đen; $bbE-$ ($\\frac{3}{16}$) lông nâu; $--ee$ ($\\frac{4}{16}$) lông vàng."},{"id":"MCQ-MD-053","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tương tác Gen","q":"Ở bí ngô, màu quả do 2 cặp gen PLĐL tương tác át chế trội: kiểu gen chứa $W-$ cho quả trắng bất kể $Y/y$; kiểu gen $wwY-$ cho quả vàng; kiểu gen $wwyy$ cho quả xanh. Khi lai phân tích cây bí quả trắng dị hợp 2 cặp gen ($WwYy \\times wwyy$), tỉ lệ kiểu hình đời con thu được là:","opts":["$1$ quả trắng : $2$ quả vàng : $1$ quả xanh.","$3$ quả trắng : $1$ quả xanh.","$2$ quả trắng : $1$ quả vàng : $1$ quả xanh.","$12$ quả trắng : $3$ quả vàng : $1$ quả xanh."],"ans":2,"exp":"$WwYy \\times wwyy \\rightarrow 1\\text{ }WwYy + 1\\text{ }Wwyy$ (2 trắng) : $1\\text{ }wwYy$ (1 vàng) : $1\\text{ }wwyy$ (1 xanh)."},{"id":"MCQ-MD-054","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Liên kết giới tính","q":"Ở ruồi giấm, gen $A$ (mắt đỏ) trội hoàn toàn so với $a$ (mắt trắng) trên vùng không tương đồng của NST X. Cho ruồi cái mắt đỏ dị hợp ($X^A X^a$) lai với ruồi đực mắt trắng ($X^a Y$). Tỉ lệ kiểu hình ở đời $F_1$ tính chung cả 2 giới là:","opts":["$3$ mắt đỏ : $1$ mắt trắng (tất cả mắt trắng đều là ruồi đực).","$1$ cái mắt đỏ : $1$ cái mắt trắng : $1$ đực mắt đỏ : $1$ đực mắt trắng.","$100\\%$ mắt đỏ.","$100\\%$ cái mắt đỏ : $100\\%$ đực mắt trắng."],"ans":1,"exp":"$X^A X^a \\times X^a Y \\rightarrow \\frac{1}{4}X^A X^a$ (cái đỏ) : $\\frac{1}{4}X^a X^a$ (cái trắng) : $\\frac{1}{4}X^A Y$ (đực đỏ) : $\\frac{1}{4}X^a Y$ (đực trắng)."},{"id":"MCQ-MD-055","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Thường biến & Thỏ Himalaya","q":"Thỏ Himalaya bình thường có bộ lông màu trắng toàn thân nhưng chóp tai, mũi, bàn chân và đuôi lại có màu đen. Nếu cạo sạch một mảng lông trắng trên lưng thỏ rồi buộc túi nước đá áp lạnh liên tục lên vùng da đó, lông mọc lại ở vùng lưng bị làm lạnh có màu đen. Giải thích nào đúng?","opts":["Enzyme tổng hợp sắc tố Melanin ở thỏ Himalaya bị bất hoạt bởi nhiệt độ cao ở vùng thân ($> 35^\\circ\\text{C}$) và chỉ hoạt động ở những vùng có nhiệt độ thấp hơn (như tai, mũi, bàn chân hoặc vùng da lưng được làm lạnh).","Nước đá đã gây đột biến gen trội tại tế bào da vùng lưng.","Tế bào lưng bị nhiễm sắc tố đen trực tiếp từ túi nước đá.","Ánh sáng mặt trời chỉ chiếu vào phần tai và mũi của thỏ."],"ans":0,"exp":"Thỏ Himalaya mang alen đột biến nhạy nhiệt độ của gen Tyrosinase: protein enzyme chỉ giữ được cấu hình hoạt động ở nhiệt độ thấp ($< 34^\\circ\\text{C}$) tại các đầu mút cơ thể."},{"id":"MCQ-MD-056","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phân ly độc lập","q":"Trong một phép lai 3 cặp gen PLĐL: $P: AaBbDd \\times AaBbDd$ (trội hoàn toàn). Tỉ lệ cá thể ở đời $F_1$ có kiểu hình mang ít nhất 1 tính trạng trội (hoặc khác kiểu hình lặn cả 3 tính trạng) là:","opts":["$\\frac{37}{64}$.","$\\frac{27}{64}$.","$\\frac{1}{64}$.","$\\frac{63}{64}$."],"ans":3,"exp":"Kiểu hình lặn cả 3 tính trạng ($aabbdd$) $= (\\frac{1}{4})^3 = \\frac{1}{64}$. Vậy tỉ lệ mang ít nhất 1 tính trạng trội $= 1 - \\frac{1}{64} = \\frac{63}{64}$."},{"id":"MCQ-MD-057","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hoán vị gen","q":"Khi thực hiện phép lai phân tích một cơ thể thực vật dị hợp 2 cặp gen $\\frac{AB}{ab} \\times \\frac{ab}{ab}$ thu được đời con gồm $4$ kiểu hình với số lượng: $420$ cây cao hoa đỏ : $420$ cây thấp hoa trắng : $80$ cây cao hoa trắng : $80$ cây thấp hoa đỏ. Tần số hoán vị gen ($f$) giữa hai gen này là:","opts":["$16\\%$.","$8\\%$.","$32\\%$.","$42\\%$."],"ans":0,"exp":"Hai lớp kiểu hình chiếm tỉ lệ nhỏ hơn là lớp tái tổ hợp (hoán vị): $f = \\frac{80 + 80}{420 + 420 + 80 + 80} \\times 100\\% = \\frac{160}{1000} \\times 100\\% = 16\\%$."},{"id":"MCQ-MD-058","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quy luật Di truyền","q":"Cho biết mỗi cặp gen quy định một tính trạng, các gen phân ly độc lập và trội hoàn toàn. Phép lai nào sau đây cho đời con có ĐỒNG THỜI tỉ lệ phân ly kiểu gen là $1:1:1:1$ và tỉ lệ phân ly kiểu hình cũng là $1:1:1:1$?","opts":["$AaBb \\times Aabb$.","$AaBb \\times aabb$.","$AABB \\times aabb$.","$AaBb \\times AaBb$."],"ans":1,"exp":"Phép lai phân tích cơ thể dị hợp 2 cặp gen PLĐL ($AaBb \\times aabb$) tạo $4$ tổ hợp giao tử tỉ lệ ngang nhau: $1\\text{ }AaBb : 1\\text{ }Aabb : 1\\text{ }aaBb : 1\\text{ }aabb$, vừa có 4 KG $1:1:1:1$ vừa có 4 KH $1:1:1:1$."},{"id":"MCQ-MD-059","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phân ly độc lập","q":"Ở một loài thực vật, gen $A$ (hoa đỏ) trội hoàn toàn so với $a$ (hoa trắng); gen $B$ (quả tròn) trội hoàn toàn so với $b$ (quả dài). Hai cặp gen phân ly độc lập. Cho cây hoa đỏ quả tròn ($AaBb$) lai với cây hoa trắng quả tròn ($aaBb$). Trong số các cây hoa đỏ quả tròn ($A-B-$) thu được ở $F_1$, tỉ lệ cây thuần chủng ($AABB$) chiếm bao nhiêu?","opts":["$\\frac{1}{3}$.","$0\\%$ (không có cây $AABB$ nào).","$\\frac{1}{9}$.","$\\frac{1}{16}$."],"ans":1,"exp":"Vì cây bố/mẹ hoa trắng quả tròn có kiểu gen $aaBb$ chỉ cho giao tử chứa $a$, nên toàn bộ đời con $F_1$ không thể có kiểu gen đồng hợp trội $AA$ (không có $AABB$)."},{"id":"MCQ-MD-060","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tương tác Gen","q":"Trong một thí nghiệm lai giống cây ngô, khi cho cây dị hợp 2 cặp gen ($AaBb$) tự thụ phấn, ở đời $F_1$ thu được tỉ lệ kiểu hình $15$ cây hạt có màu : $1$ cây hạt trắng (tương tác cộng gộp kiểu ngưỡng trội). Nếu cho cây $AaBb$ đem lai phân tích với cây hạt trắng ($aabb$), tỉ lệ kiểu hình ở đời con là:","opts":["$15$ cây hạt có màu : $1$ cây hạt trắng.","$3$ cây hạt có màu : $1$ cây hạt trắng.","$1$ cây hạt có màu : $1$ cây hạt trắng.","$1$ cây hạt có màu : $3$ cây hạt trắng."],"ans":1,"exp":"Kiểu $15:1$ nghĩa là chỉ cần có ít nhất $1$ alen trội ($A$ hoặc $B$) đều cho hạt có màu, duy nhất $aabb$ cho hạt trắng. Khi $AaBb \\times aabb \\rightarrow 1AaBb + 1Aabb + 1aaBb$ (3 có màu) : $1aabb$ (1 trắng)."},{"id":"MCQ-MD-061","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Liên kết giới tính","q":"Bệnh mù màu đỏ - lục ở người do gen lặn $m$ nằm trên vùng không tương đồng của NST X quy định. Một người phụ nữ có thị giác bình thường nhưng có BỐ bị mù màu kết hôn với một người đàn ông có thị giác bình thường. Xác suất họ sinh được một người con trai bị mù màu là:","opts":["$0\\%$.","$\\frac{1}{4}$ ($25\\%$).","$\\frac{1}{8}$ ($12.5\\%$).","$\\frac{1}{2}$ ($50\\%$)."],"ans":1,"exp":"Người phụ nữ bình thường có bố bị mù màu ($X^m Y$) chắc chắn nhận $X^m$ từ bố nên có kiểu gen $X^M X^m$. Chồng bình thường là $X^M Y$. Sinh con trai bị bệnh ($X^m Y$) chiếm $\\frac{1}{4} = 25\\%$ tổng số con."},{"id":"MCQ-MD-062","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Số loại giao tử","q":"Một cơ thể thực vật có kiểu gen $AaBb\\frac{DE}{de}$ tiến hành giảm phân bình thường tạo giao tử. Biết có xảy ra hoán vị gen giữa $D$ và $E$ với tần số $20\\%$. Số loại giao tử tối đa có thể tạo thành từ cơ thể này là:","opts":["$32$ loại.","$8$ loại.","$12$ loại.","$16$ loại."],"ans":3,"exp":"Cặp $Aa$: $2$ loại; Cặp $Bb$: $2$ loại; Cặp $\\frac{DE}{de}$ có hoán vị gen: $4$ loại. Tổng số loại giao tử $= 2 \\times 2 \\times 4 = 16$ loại."},{"id":"MCQ-MD-063","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phép lai một cặp gen","q":"Ở một loài thú, alen $A$ (lông xám) trội hoàn toàn so với $a$ (lông trắng). Cho một con đực lông xám giao phối với một con cái lông xám, đời con sinh ra được 1 con lông xám và 1 con lông trắng. Kiểu gen của cặp bố mẹ ban đầu chắc chắn là:","opts":["$Aa \\times aa$.","$Aa \\times Aa$.","$AA \\times AA$.","$AA \\times Aa$."],"ans":1,"exp":"Bố mẹ đều lông xám (mang ít nhất 1 alen $A$) nhưng sinh ra con lông trắng ($aa$) nên cả bố và mẹ đều phải cho được giao tử $a \\Rightarrow$ Cả hai đều dị hợp $Aa$."},{"id":"MCQ-MD-064","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Bản đồ gen","q":"Trên một nhiễm sắc thể có 3 gen liên kết $A, B, C$. Tần số hoán vị gen giữa $A$ và $B$ là $15\\%$, giữa $B$ và $C$ là $25\\%$, giữa $A$ và $C$ là $10\\%$. Trật tự phân bố đúng của 3 gen trên nhiễm sắc thể đó là:","opts":["$A - B - C$.","$A - C - B$.","Không xác định được.","$B - A - C$ (hoặc $C - A - B$)."],"ans":3,"exp":"Khoảng cách lớn nhất là $d(B, C) = 25\\text{ cM} = d(B, A) + d(A, C) = 15 + 10 = 25\\text{ cM} \\Rightarrow$ Gen $A$ nằm giữa $B$ và $C$."},{"id":"MCQ-MD-065","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Di truyền Liên kết","q":"Phép lai nào sau đây (biết các gen liên kết hoàn toàn, trội hoàn toàn) tạo ra đời con có tỉ lệ kiểu hình $3$ trội cả hai tính trạng : $1$ lặn cả hai tính trạng?","opts":["$\\frac{Ab}{aB} \\times \\frac{Ab}{aB}$.","$\\frac{Ab}{ab} \\times \\frac{aB}{ab}$.","$\\frac{AB}{ab} \\times \\frac{Ab}{aB}$.","$\\frac{AB}{ab} \\times \\frac{AB}{ab}$."],"ans":3,"exp":"$\\frac{AB}{ab} \\times \\frac{AB}{ab}$ (liên kết hoàn toàn): mỗi bên cho $\\frac{1}{2}\\underline{AB} : \\frac{1}{2}\\underline{ab} \\rightarrow 1\\frac{AB}{AB} + 2\\frac{AB}{ab}$ (3 trội cả 2 tính) : $1\\frac{ab}{ab}$ (1 lặn cả 2 tính)."},{"id":"MCQ-MD-066","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quy luật Di truyền","q":"Khi nghiên cứu một tính trạng do gen nằm trên nhiễm sắc thể thường quy định, phép lai thuận và phép lai nghịch cho kết quả hoàn toàn giống nhau ở cả hai giới. Ngược lại, nếu kết quả lai thuận và lai nghịch khác nhau và con luôn biểu hiện kiểu hình giống mẹ ở $100\\%$ đời con, tính trạng đó di truyền theo quy luật nào?","opts":["Phân ly độc lập của Mendel.","Liên kết hoàn toàn trên NST thường.","Di truyền qua tế bào chất (gen ngoài nhân ở lục lạp hoặc ti thể).","Tương tác cộng gộp."],"ans":2,"exp":"Đặc điểm nhận biết kinh điển của di truyền ngoài nhân: kết quả lai thuận $\\ne$ lai nghịch và đời con luôn $100\\%$ theo dòng mẹ (khác với di truyền chéo của gen trên X)."},{"id":"MCQ-MD-067","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Di truyền Y học","q":"Ở người, bệnh bạch tạng do gen lặn $a$ trên NST thường quy định; alen $A$ quy định da bình thường trội hoàn toàn. Một cặp vợ chồng bình thường đều mang gen dị hợp $Aa$ sinh được $1$ đứa con có kiểu hình bình thường. Xác suất đứa con bình thường này mang kiểu gen dị hợp $Aa$ là bao nhiêu?","opts":["$\\frac{2}{3}$.","$\\frac{1}{2}$.","$\\frac{3}{4}$.","$\\frac{1}{3}$."],"ans":0,"exp":"$Aa \\times Aa \\rightarrow \\frac{1}{4}AA : \\frac{2}{4}Aa : \\frac{1}{4}aa$. Trong số các con bình thường ($1AA : 2Aa$), tỉ lệ dị hợp $Aa$ là $\\frac{2}{3}$."},{"id":"MCQ-MD-068","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hoán vị gen 2 giới","q":"Cho phép lai $P: \\frac{AB}{ab} \\times \\frac{Ab}{aB}$, biết hai cặp gen quy định 2 tính trạng trội hoàn toàn và xảy ra hoán vị gen ở cả 2 giới với tần số $f = 40\\%$. Tổng tỉ lệ cá thể ở đời con $F_1$ có kiểu hình mang $1$ tính trạng trội và $1$ tính trạng lặn ($A-bb$ hoặc $aaB-$) là:","opts":["$19\\%$.","$56\\%$.","$42\\%$.","$38\\%$."],"ans":3,"exp":"$\\underline{ab}_1 = 0.3$; $\\underline{ab}_2 = 0.2 \\Rightarrow \\%aabb = 0.3 \\times 0.2 = 6\\%$. Áp dụng hệ thức: $\\%A-bb = \\%aaB- = 25\\% - 6\\% = 19\\% \\Rightarrow$ Tổng $A-bb + aaB- = 38\\%$."},{"id":"MCQ-MD-069","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hoán vị gen 1 giới","q":"Ở ruồi giấm (hoán vị gen chỉ xảy ra ở giới cái), cho phép lai $P: \\text{♀ } \\frac{AB}{ab} \\times \\text{♂ } \\frac{AB}{ab}$ (trội hoàn toàn), biết tần số hoán vị gen ở ruồi cái là $f = 20\\%$. Tỉ lệ ruồi ở $F_1$ mang kiểu hình trội về $A$ và lặn về $B$ ($A-bb$) là:","opts":["$10\\%$.","$20\\%$.","$5\\%$.","$25\\%$."],"ans":2,"exp":"Ruồi cái ($f=20\\%$) cho $\\underline{ab} = 0.4$; ruồi đực không hoán vị cho $\\underline{ab} = 0.5 \\Rightarrow \\%aabb = 0.4 \\times 0.5 = 20\\%$. Áp dụng hệ thức Morgan: $\\%A-bb = 25\\% - \\%aabb = 25\\% - 20\\% = 5\\%$."},{"id":"MCQ-MD-070","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hoán vị gen + Giới tính","q":"Ở một loài thú ($XX/XY$), xét phép lai $P: \\text{♀ } \\frac{AB}{ab} X^D X^d \\times \\text{♂ } \\frac{AB}{ab} X^D Y$ (các gen trội hoàn toàn, hoán vị gen xảy ra ở cả 2 giới với tần số như nhau). Đời $F_1$ thu được cá thể mang kiểu hình lặn cả 3 tính trạng ($aabb X^d Y$) chiếm tỉ lệ $2.25\\%$. Tần số hoán vị gen ($f$) giữa $A$ và $B$ là:","opts":["$15\\%$.","$40\\%$.","$30\\%$.","$20\\%$."],"ans":1,"exp":"$X^D X^d \\times X^D Y \\rightarrow \\frac{1}{4} X^d Y$. Vậy $\\%aabb = \\frac{2.25\\%}{0.25} = 9\\% = 0.09 \\Rightarrow \\underline{ab} = \\sqrt{0.09} = 0.3 > 0.25$ (giao tử liên kết) $\\Rightarrow f = 2(0.5 - 0.3) = 40\\%$."},{"id":"MCQ-MD-071","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tính số kiểu gen HVG","q":"Cho phép lai $P: \\frac{AB}{ab} \\frac{De}{dE} \\times \\frac{Ab}{aB} \\frac{DE}{de}$, biết ở cả 2 giới đều xảy ra hoán vị gen giữa $A-B$ và giữa $D-E$. Tổng số loại kiểu gen tối đa có thể xuất hiện ở đời con $F_1$ là:","opts":["$64$ kiểu gen.","$100$ kiểu gen.","$49$ kiểu gen.","$81$ kiểu gen."],"ans":1,"exp":"Khi cả bố và mẹ đều dị hợp 2 cặp gen nằm trên cùng 1 NST và đều có hoán vị gen, mỗi cặp NST tạo tối đa $10$ loại kiểu gen (do $4$ loại giao tử $\\times 4$ loại giao tử cho $10$ KG). Với 2 cặp NST độc lập: $10 \\times 10 = 100$ kiểu gen."},{"id":"MCQ-MD-072","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tương tác Gen & Hoán vị","q":"Ở một loài thực vật, chiều cao cây do hai cặp gen $(A, a)$ và $(B, b)$ tác động cộng gộp: mỗi alen trội làm cây cao thêm $10\\text{ cm}$, cây $aabb$ cao $100\\text{ cm}$. Biết hai gen này cùng nằm trên 1 cặp NST. Cho cây $\\frac{Ab}{aB}$ tự thụ phấn với hoán vị gen ở cả 2 giới có tần số $f = 20\\%$. Tỉ lệ cây có chiều cao $120\\text{ cm}$ ở đời $F_1$ là:","opts":["$34\\%$.","$66\\%$.","$37.5\\%$.","$32\\%$."],"ans":1,"exp":"Cây cao $120\\text{ cm}$ có $2$ alen trội ($\\frac{AB}{ab}, \\frac{Ab}{aB}, \\frac{Ab}{Ab}, \\frac{aB}{aB}$). Cây $\\frac{Ab}{aB}$ ($f=20\\%$) tạo $\\underline{Ab}=\\underline{aB}=0.4; \\underline{AB}=\\underline{ab}=0.1$. Tổng tỉ lệ $= 2(0.1)^2 + 2(0.4)^2 + (0.4)^2 + (0.4)^2 = 0.02 + 0.32 + 0.16 + 0.16 = 66\\%$."},{"id":"MCQ-MD-073","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tương tác Bổ sung","q":"Ở một loài hoa, màu hoa do 2 cặp gen PLĐL $(A,a)$ và $(B,b)$ tương tác bổ sung: $A-B-$ quy định hoa đỏ; $A-bb$ và $aaB-$ quy định hoa hồng; $aabb$ quy định hoa trắng. Cho hai cây hoa hồng lai với nhau ($P$) thu được $F_1$ gồm toàn hoa đỏ ($100\\%$). Khi cho các cây hoa đỏ $F_1$ giao phấn ngẫu nhiên với nhau thì tỉ lệ kiểu hình ở đời $F_2$ thu được là:","opts":["$9$ đỏ : $6$ hồng : $1$ trắng.","$1$ đỏ : $2$ hồng : $1$ trắng.","$100\\%$ đỏ.","$9$ đỏ : $7$ trắng."],"ans":0,"exp":"Hai cây hoa hồng lai ra $100\\%$ hoa đỏ chỉ có thể là $AAbb \\times aaBB \\rightarrow F_1: 100\\% AaBb$ (đỏ). $F_1$ giao phấn tạo $F_2$: $9/16\\text{ }A-B-$ (đỏ) : $6/16\\text{ }(A-bb + aaB-)$ (hồng) : $1/16\\text{ }aabb$ (trắng)."},{"id":"MCQ-MD-074","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tương tác Bổ sung & Giao tử","q":"Ở bí ngô, dạng quả do 2 cặp gen PLĐL quy định: $A-B-$ quả dẹt; $A-bb$ và $aaB-$ quả tròn; $aabb$ quả dài. Nếu cho cây quả dẹt dị hợp 2 cặp gen ($AaBb$) lai với cây quả tròn dị hợp ($Aabb$), tỉ lệ kiểu hình ở đời con là:","opts":["$3$ quả dẹt : $4$ quả tròn : $1$ quả dài.","$3$ quả dẹt : $1$ quả tròn.","$9$ quả dẹt : $6$ quả tròn : $1$ quả dài.","$1$ quả dẹt : $2$ quả tròn : $1$ quả dài."],"ans":0,"exp":"$Aa \\times Aa \\rightarrow \\frac{3}{4}A- : \\frac{1}{4}aa$; $Bb \\times bb \\rightarrow \\frac{1}{2}B- : \\frac{1}{2}bb$. Nhân tổ hợp: $A-B- = \\frac{3}{8}$ (dẹt); $A-bb + aaB- = \\frac{3}{8} + \\frac{1}{8} = \\frac{4}{8}$ (tròn); $aabb = \\frac{1}{8}$ (dài) $\\Rightarrow 3:4:1$."},{"id":"MCQ-MD-075","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tương tác Át chế 13:3","q":"Ở gà, bộ lông trắng hay màu do 2 cặp gen PLĐL quy định: alen $C$ quy định tổng hợp sắc tố (lông màu), $c$ không tạo sắc tố (trắng); alen $I$ ức chế hoàn toàn sự biểu hiện của $C$ (nên $C-I-$, $ccI-$, $ccii$ đều lông trắng; duy nhất $C-ii$ lông màu). Cho hai con gà lông trắng thuần chủng khác nhau ($CCII \\times ccii$) giao phối tạo $F_1$ lông trắng, rồi cho $F_1$ giao phối với nhau thu $F_2$. Trong số các con gà LÔNG TRẮNG ở $F_2$, tỉ lệ gà mang kiểu gen thuần chủng chiếm:","opts":["$\\frac{4}{13}$.","$\\frac{1}{16}$.","$\\frac{3}{13}$.","$\\frac{3}{16}$."],"ans":2,"exp":"$F_2$ có $13$ trắng : $3$ màu. Các kiểu gen trắng thuần chủng gồm $CCII (\\frac{1}{16})$, $ccII (\\frac{1}{16})$ và $ccii (\\frac{1}{16})$, tổng cộng $\\frac{3}{16}$. Trong số $\\frac{13}{16}$ gà lông trắng, gà thuần chủng chiếm $\\frac{3}{13}$."},{"id":"MCQ-MD-076","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tương tác Cộng gộp","q":"Cân nặng quả ở một giống cây do $3$ cặp gen $(Aa, Bb, Dd)$ PLĐL tương tác cộng gộp quy định. Cây nặng nhất ($AABBDD$) cho quả nặng $210\\text{ g}$, cây nhẹ nhất ($aabbdd$) cho quả nặng $90\\text{ g}$. Khi cho cây dị hợp cả 3 cặp gen ($AaBbDd$) tự thụ phấn, loại quả nặng $150\\text{ g}$ ở đời $F_1$ chiếm tỉ lệ bao nhiêu?","opts":["$\\frac{1}{64}$.","$\\frac{6}{64}$.","$\\frac{5}{16}$ ($\\frac{20}{64}$).","$\\frac{15}{64}$."],"ans":2,"exp":"Mỗi alen trội đóng góp $\\frac{210 - 90}{6} = 20\\text{ g}$. Quả nặng $150\\text{ g}$ chứa $\\frac{150 - 90}{20} = 3$ alen trội. Tỉ lệ cá thể có 3 alen trội từ $AaBbDd \\times AaBbDd$ là $\\frac{C^3_6}{2^6} = \\frac{20}{64} = \\frac{5}{16}$."},{"id":"MCQ-MD-077","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Gen gây chết","q":"Ở chuột, alen $A^Y$ (lông vàng) trội hoàn toàn so với alen $a$ (lông xám), nhưng ở trạng thái đồng hợp $A^Y A^Y$ thì phôi chuột bị chết trước khi sinh. Một nhà nghiên cứu cho lai 1 con chuột lông vàng với 1 con chuột lông vàng ($A^Y a \\times A^Y a$), sau đó lấy ngẫu nhiên các con chuột lông vàng ở đời $F_1$ cho giao phối ngẫu nhiên với nhau. Tỉ lệ kiểu hình (lông vàng : lông xám) trong số các chuột con $F_2$ sống sót sau khi sinh là:","opts":["$2$ lông vàng : $1$ lông xám.","$1$ lông vàng : $1$ lông xám.","$100\\%$ lông vàng.","$3$ lông vàng : $1$ lông xám."],"ans":0,"exp":"Tất cả các con chuột lông vàng trưởng thành đều bắt buộc mang kiểu gen dị hợp $A^Y a$ (vì $A^Y A^Y$ đã chết phôi). Khi $A^Y a \\times A^Y a$, tỉ lệ sống sót vẫn luôn là $\\frac{2}{3} A^Y a$ (vàng) : $\\frac{1}{3} aa$ (xám)."},{"id":"MCQ-MD-078","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Liên kết giới tính","q":"Ở ruồi giấm, alen $A$ (thân xám) trội hoàn toàn so với $a$ (thân đen), $B$ (cánh dài) trội hoàn toàn so với $b$ (cánh cụt) cùng nằm trên 1 cặp NST thường; alen $D$ (mắt đỏ) trội hoàn toàn so với $d$ (mắt trắng) nằm trên vùng không tương đồng của NST X. Cho ruồi cái thân xám, cánh dài, mắt đỏ lai với ruồi đực thân xám, cánh dài, mắt đỏ, đời $F_1$ thu được $1\\%$ số cá thể có kiểu hình thân đen, cánh cụt, mắt trắng ($\\frac{ab}{ab} X^d Y$). Biết ở ruồi giấm con đực không có HVG. Tần số hoán vị gen ở ruồi cái mẹ là bao nhiêu?","opts":["$20\\%$.","$4\\%$.","$8\\%$.","$16\\%$."],"ans":3,"exp":"Do ruồi bố là $\\frac{AB}{ab} X^D Y$ mới sinh được con thân đen cánh cụt mắt trắng ($\\%X^d Y = 0.25$ từ $X^D X^d \\times X^D Y$). Suy ra $\\frac{ab}{ab} = \\frac{1\\%}{0.25} = 4\\% = \\underline{ab}_{\\text{cái}} \\times 0.5_{\\text{đực}} \\Rightarrow \\underline{ab}_{\\text{cái}} = 0.08 < 0.25$ (giao tử hoán vị!) $\\Rightarrow f = 2 \\times 0.08 = 16\\%$! (Rất hay: kiểu gen ruồi cái mẹ là dị hợp chéo $\\frac{Ab}{aB}$!)."},{"id":"MCQ-MD-079","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Di truyền vùng tương đồng X-Y","q":"Ở một loài động vật ($XX/XY$), xét một gen có 2 alen $A$ và $a$ nằm trên vùng tương đồng của cả hai nhiễm sắc thể giới tính $X$ và $Y$. Phép lai $P: \\text{♀ } X^A X^a \\times \\text{♂ } X^a Y^A$ cho tỉ lệ kiểu hình ở đời con $F_1$ phân bố theo giới tính như thế nào?","opts":["Cả hai giới đều $3$ trội : $1$ lặn.","Ở giới cái: $100\\%$ trội; Ở giới đực: $1$ trội : $1$ lặn.","Cả hai giới đều $100\\%$ trội.","Ở giới cái ($XX$): $1$ trội : $1$ lặn ($X^A X^a : X^a X^a$); Ở giới đực ($XY$): $100\\%$ trội ($X^A Y^A$ và $X^a Y^A$)."],"ans":3,"exp":"Bố $X^a Y^A$ truyền $X^a$ cho toàn bộ con gái và truyền $Y^A$ (mang alen trội $A$) cho toàn bộ con trai, nên $100\\%$ con trai mang kiểu hình trội, còn con gái chia $1$ trội : $1$ lặn."},{"id":"MCQ-MD-080","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phụ thuộc giới tính","q":"Ở cừu, kiểu gen $HH$ có sừng ở cả hai giới; $hh$ không sừng ở cả hai giới; kiểu gen dị hợp $Hh$ biểu hiện CÓ SỪNG ở cừu đực nhưng KHÔNG SỪNG ở cừu cái (do ảnh hưởng của hormone sinh dục). Thực hiện phép lai giữa cừu đực không sừng ($hh$) và cừu cái có sừng ($HH$). Cho $F_1$ giao phối ngẫu nhiên với nhau thu được $F_2$. Tỉ lệ kiểu hình ở $F_2$ tính riêng cho giới đực và giới cái lần lượt là:","opts":["Cả giới đực và giới cái đều có $3$ có sừng : $1$ không sừng.","Giới đực: $100\\%$ có sừng; Giới cái: $100\\%$ không sừng.","Giới đực: $3$ có sừng : $1$ không sừng; Giới cái: $1$ có sừng : $3$ không sừng.","Giới đực: $1$ có sừng : $3$ không sừng; Giới cái: $3$ có sừng : $1$ không sừng."],"ans":2,"exp":"$F_1$ $100\\% Hh$. $F_1 \\times F_1 \\rightarrow F_2: \\frac{1}{4}HH : \\frac{2}{4}Hh : \\frac{1}{4}hh$ ở mỗi giới. Ở đực, $HH + Hh$ có sừng ($\\frac{3}{4}$); ở cái chỉ $HH$ có sừng ($\\frac{1}{4}$)."},{"id":"MCQ-MD-081","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Di truyền trên NST Z","q":"Ở chim bồ câu (đực $ZZ$, cái $ZW$), tính trạng màu lông do 1 gen nằm trên vùng không tương đồng của NST $Z$ quy định: $B$ (lông xanh) trội hoàn toàn so với $b$ (lông nâu). Phép lai $P$ giữa chim trống lông xanh và chim mái lông nâu cho đời $F_1$ toàn lông xanh; sau đó cho $F_1$ ngẫu phối thu $F_2$. Tỉ lệ phân ly kiểu hình ở đời $F_2$ là:","opts":["$100\\%$ chim trống lông xanh ($Z^B Z^B, Z^B Z^b$) và $1$ chim mái lông xanh ($Z^B W$) : $1$ chim mái lông nâu ($Z^b W$).","$100\\%$ trống nâu và $100\\%$ mái xanh.","$3$ trống xanh : $1$ trống nâu; $100\\%$ mái xanh.","$1$ trống xanh : $1$ trống nâu : $1$ mái xanh : $1$ mái nâu."],"ans":0,"exp":"Trống $Z^B Z^B \\times$ Mái $Z^b W \\rightarrow F_1: Z^B Z^b \\times Z^B W \\rightarrow F_2$: trống ($\\frac{1}{4}Z^B Z^B : \\frac{1}{4}Z^B Z^b$ đều xanh), mái ($\\frac{1}{4}Z^B W$ xanh : $\\frac{1}{4}Z^b W$ nâu)."},{"id":"MCQ-MD-082","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quy luật Tổ hợp","q":"Xét phép lai $P: AaBbDdEe \\times AaBbddEe$ (các cặp gen PLĐL, trội hoàn toàn). Tỉ lệ cá thể ở đời $F_1$ có kiểu hình mang ĐÚNG $3$ tính trạng trội và $1$ tính trạng lặn là bao nhiêu?","opts":["$\\frac{27}{64}$.","$\\frac{9}{64}$.","$\\frac{27}{128}$.","$\\frac{45}{128}$."],"ans":0,"exp":"TH1: $dd (\\frac{1}{2})$ và 3 cặp kia đều trội $((\\frac{3}{4})^3) = \\frac{27}{128}$. TH2: $D- (\\frac{1}{2})$ và 3 cặp kia có 2 trội + 1 lặn $(C^2_3 (\\frac{3}{4})^2 \\frac{1}{4}) = \\frac{27}{128}$. Tổng xác suất $= \\frac{27}{128} + \\frac{27}{128} = \\frac{54}{128} = \\frac{27}{64}$."},{"id":"MCQ-MD-083","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Số kiểu phép lai","q":"Ở một loài thực vật lưỡng bội, xét 2 cặp gen nằm trên 2 cặp NST khác nhau: gen thứ nhất có $3$ alen, gen thứ hai có $2$ alen. Nếu phân biệt vai trò làm bố và làm mẹ (phép lai thuận khác phép lai nghịch về ký hiệu giới tính bố $\\times$ mẹ), trong quần thể có tối đa bao nhiêu kiểu phép lai khác nhau?","opts":["$18$ phép lai.","$171$ phép lai.","$324$ phép lai.","$36$ phép lai."],"ans":2,"exp":"Gen 1 có $\\frac{3\\times 4}{2} = 6$ KG; gen 2 có $\\frac{2\\times 3}{2} = 3$ KG $\\Rightarrow$ Tổng số KG trong quần thể $G = 6 \\times 3 = 18$. Khi phân biệt vai trò bố và mẹ: số phép lai $= G \\times G = 18^2 = 324$ phép lai."},{"id":"MCQ-MD-084","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đếm số kiểu gen tự nhiên","q":"Một loài thú có cặp NST giới tính $XX/XY$. Xét Gen 1 có $4$ alen nằm trên vùng không tương đồng của NST X; Gen 2 có $3$ alen nằm trên NST thường. Tổng số kiểu gen tối đa có thể tạo ra trong quần thể loài này là bao nhiêu?","opts":["$84$ kiểu gen.","$60$ kiểu gen.","$140$ kiểu gen.","$48$ kiểu gen."],"ans":0,"exp":"Gen 2 (NST thường): $\\frac{3 \\times 4}{2} = 6$ KG. Gen 1 (trên X không có trên Y): giới cái $XX$ có $\\frac{4 \\times 5}{2} = 10$ KG; giới đực $XY$ có $4$ KG $\\Rightarrow$ tổng trên X là $10 + 4 = 14$ KG. Tổng cả 2 gen $= 6 \\times 14 = 84$ kiểu gen."},{"id":"MCQ-MD-085","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tương tác & Liên kết","q":"Tính trạng chiều cao cây do 2 cặp gen quy định theo kiểu cộng gộp: cây $AABB$ cao $200\\text{ cm}$, cây $aabb$ cao $160\\text{ cm}$, mỗi alen trội làm tăng $10\\text{ cm}$. Khi lai cây cao $180\\text{ cm}$ dị hợp 2 cặp gen với cây cao $170\\text{ cm}$ (biết 2 gen PLĐL), tỉ lệ cây cao $190\\text{ cm}$ ở đời $F_1$ là:","opts":["$\\frac{3}{8}$ ($37.5\\%$).","$\\frac{1}{16}$.","$\\frac{1}{8}$ ($12.5\\%$).","$\\frac{1}{4}$ ($25\\%$)."],"ans":2,"exp":"Cây cao $180\\text{ cm}$ dị hợp 2 cặp là $AaBb$; cây cao $170\\text{ cm}$ có $1$ alen trội (giả sử $Aabb$ hoặc $aaBb$). Trong phép lai $AaBb \\times Aabb$, cây cao $190\\text{ cm}$ phải có $3$ alen trội ($AABb$): $AA (\\frac{1}{4}) \\times Bb (\\frac{1}{2}) = \\frac{1}{8}$."},{"id":"MCQ-MD-086","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hoán vị gen từ % tế bào","q":"Trong quá trình giảm phân của một cơ thể thực vật có kiểu gen $\\frac{AB}{ab}$, khi quan sát $500$ tế bào sinh hạt phấn thấy có $120$ tế bào xảy ra trao đổi chéo tại 1 điểm giữa $A$ và $B$, các tế bào còn lại giảm phân không trao đổi chéo. Tỉ lệ phần trăm các loại giao tử tạo thành là:","opts":["$\\underline{AB} = \\underline{ab} = 24\\%$; $\\underline{Ab} = \\underline{aB} = 26\\%$.","$\\underline{AB} = \\underline{ab} = 44\\%$; $\\underline{Ab} = \\underline{aB} = 6\\%$.","$\\underline{AB} = \\underline{ab} = 38\\%$; $\\underline{Ab} = \\underline{aB} = 12\\%$.","$\\underline{AB} = \\underline{ab} = 47\\%$; $\\underline{Ab} = \\underline{aB} = 3\\%$."],"ans":1,"exp":"Tỉ lệ tế bào có TĐC $= \\frac{120}{500} = 24\\% \\Rightarrow$ Tần số HVG $f = \\frac{24\\%}{2} = 12\\%$. Vậy giao tử liên kết $\\underline{AB} = \\underline{ab} = 50\\% - 6\\% = 44\\%$; giao tử hoán vị $\\underline{Ab} = \\underline{aB} = 6\\%$."},{"id":"MCQ-MD-087","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Biện luận phép lai Hoán vị","q":"Ở một loài thực vật, cho cây thân cao, hoa trắng thuần chủng lai với cây thân thấp, hoa đỏ thuần chủng thu được $F_1$ toàn bộ thân cao, hoa đỏ. Cho $F_1$ lai phân tích thu được đời con $F_a$ gồm: $40\\%$ cao trắng : $40\\%$ thấp đỏ : $10\\%$ cao đỏ : $10\\%$ thấp trắng. Kiểu gen của $F_1$ và tần số hoán vị gen ($f$) lần lượt là:","opts":["$\\frac{Ab}{aB}$ và $f = 40\\%$.","$\\frac{Ab}{aB}$ và $f = 20\\%$.","$\\frac{AB}{ab}$ và $f = 20\\%$.","$\\frac{AB}{ab}$ và $f = 40\\%$."],"ans":1,"exp":"$F_1$ nhận $\\underline{Ab}$ từ bố/mẹ Cao Trắng và $\\underline{aB}$ từ bên Thấp Đỏ nên có kiểu gen dị hợp chéo $\\frac{Ab}{aB}$. Ở $F_a$, hai lớp tái tổ hợp (Cao Đỏ + Thấp Trắng) $= 10\\% + 10\\% = 20\\% \\Rightarrow f = 20\\%$."},{"id":"MCQ-MD-088","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Bản đồ Gen 2 điểm","q":"Hai gen $M$ và $N$ cùng nằm trên một nhiễm sắc thể và cách nhau $28\\text{ cM}$. Một cá thể mang kiểu gen $\\frac{MN}{mn}$ giảm phân bình thường có HVG theo đúng khoảng cách bản đồ. Tỉ lệ loại giao tử $\\underline{Mn}$ tạo ra là:","opts":["$36\\%$.","$7\\%$.","$14\\%$.","$28\\%$."],"ans":2,"exp":"Khoảng cách $28\\text{ cM}$ tương ứng tần số HVG $f = 28\\%$. Với dị hợp đều $\\frac{MN}{mn}$, giao tử hoán vị $\\underline{Mn} = \\underline{mN} = \\frac{f}{2} = 14\\%$."},{"id":"MCQ-MD-089","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hoán vị + PLĐL","q":"Cho phép lai $P: Aa\\frac{BD}{bd} \\times Aa\\frac{BD}{bd}$ (biết mỗi gen quy định một tính trạng, trội hoàn toàn; ở cả hai giới có hoán vị giữa $B$ và $D$ với tần số $f = 20\\%$). Tỉ lệ cá thể đời con $F_1$ mang kiểu hình đồng hợp lặn về cả 3 tính trạng ($aa\\frac{bd}{bd}$) là:","opts":["$1\\%$.","$8\\%$.","$4\\%$.","$16\\%$."],"ans":2,"exp":"$Aa \\times Aa \\rightarrow \\frac{1}{4}aa = 0.25$. Bên $\\frac{BD}{bd}$ ($f=20\\%$) cho $\\underline{bd} = 0.4 \\Rightarrow \\frac{bd}{bd} = (0.4)^2 = 0.16$. Tích xác suất $= 0.25 \\times 0.16 = 0.04 = 4\\%$."},{"id":"MCQ-MD-090","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tương tác + Hoán vị","q":"Ở một loài hoa, màu hoa do 2 cặp gen $(A, a)$ và $(B, b)$ cùng nằm trên 1 cặp NST quy định theo kiểu tương tác bổ sung: có đồng thời $A$ và $B$ ($A-B-$) cho hoa đỏ; các kiểu gen còn lại cho hoa trắng. Cho cây $\\frac{AB}{ab}$ tự thụ phấn (có HVG với $f = 30\\%$ ở cả hai giới). Tỉ lệ cây hoa ĐỎ thu được ở $F_1$ là:","opts":["$62.25\\%$.","$56.25\\%$.","$68.25\\%$.","$50.25\\%$."],"ans":0,"exp":"$\\%\\underline{ab} = 0.5 - \\frac{0.3}{2} = 0.35 \\Rightarrow \\%\\frac{ab}{ab} = (0.35)^2 = 0.1225 = 12.25\\%$. Áp dụng hệ thức Morgan: $\\%A-B- = 50\\% + \\%aabb = 50\\% + 12.25\\% = 62.25\\%$."},{"id":"MCQ-MD-091","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đếm số kiểu gen tự nhiên","q":"Ở một loài thú, gen $A$ (màu lông) có $3$ alen nằm trên vùng không tương đồng của NST X; gen $B$ (chiều dài tai) có $4$ alen nằm trên NST thường; gen $D$ (túm lông tai) có $2$ alen nằm trên vùng không tương đồng của NST Y. Tổng số kiểu gen tối đa có thể có ở GIỚI ĐỰC ($XY$) của loài này là:","opts":["$120$ kiểu gen.","$90$ kiểu gen.","$60$ kiểu gen.","$30$ kiểu gen."],"ans":2,"exp":"Gen $B$ (NST thường): $\\frac{4\\times 5}{2} = 10$ KG. Ở giới đực $XY$: trên X có $3$ cách chọn, trên Y có $2$ cách chọn $\\Rightarrow 3 \\times 2 = 6$ KG giới tính. Tổng ở giới đực $= 10 \\times 6 = 60$ kiểu gen."},{"id":"MCQ-MD-092","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hiệu ứng dòng mẹ","q":"Ở ốc nước ngọt <i>Limnaea peregra</i>, kiểu xoắn vỏ do gen nhân $D$ (xoắn phải) trội hoàn toàn so với $d$ (xoắn trái) quy định nhưng di truyền theo hiệu ứng dòng mẹ (kiểu hình của con phụ thuộc vào kiểu gen của mẹ). Lấy trứng của ốc mẹ có kiểu gen $dd$ (có vỏ xoắn phải do bà ngoại dị hợp) cho thụ tinh với tinh trùng của ốc bố thuần chủng $DD$. Kiểu hình của $F_1$ và của $F_2$ (khi $F_1$ tự thụ tinh) lần lượt là:","opts":["$F_1$: $100\\%$ xoắn phải; $F_2$: $3$ xoắn phải : $1$ xoắn trái.","$F_1$: $100\\%$ xoắn trái (theo $dd$ của mẹ); $F_2$: $100\\%$ xoắn phải (theo $Dd$ của $F_1$).","$F_1$: $100\\%$ xoắn trái; $F_2$: $3$ xoắn phải : $1$ xoắn trái.","$F_1$: $100\\%$ xoắn phải; $F_2$: $100\\%$ xoắn trái."],"ans":1,"exp":"Mẹ $dd$ tạo $F_1$ ($100\\% Dd$) nhưng mRNA dự trữ trong trứng từ mẹ $dd$ nên $F_1$ có vỏ $100\\%$ xoắn trái. Đến lượt $F_1$ ($Dd$) làm mẹ tự thụ tạo $F_2$: nhờ có alen $D$ trong kiểu gen của $F_1$, $100\\%$ con $F_2$ đều xoắn phải! (Tỉ lệ $3:1$ chỉ xuất hiện muộn ở $F_3$)."},{"id":"MCQ-MD-093","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Liên kết giới tính + PLĐL","q":"Ở ruồi giấm, mắt đỏ ($W$) trội hoàn toàn so với mắt trắng ($w$) nằm trên NST X; thân xám ($B$) trội hoàn toàn so với thân đen ($b$) nằm trên NST thường. Cho phép lai $P: \\text{♀ } Bb X^W X^w \\times \\text{♂ } Bb X^W Y$. Trong số các ruồi ĐỰC thu được ở đời $F_1$, tỉ lệ ruồi thân xám, mắt đỏ ($B- X^W Y$) chiếm tỉ lệ bao nhiêu?","opts":["$\\frac{3}{16}$ ($18.75\\%$).","$\\frac{1}{4}$.","$\\frac{9}{16}$.","$\\frac{3}{8}$ ($37.5\\%$)."],"ans":3,"exp":"Cẩn thận câu hỏi: 'TRONG SỐ CÁC RUỒI ĐỰC' ở $F_1$! Ở giới đực, $B- = \\frac{3}{4}$ và $X^W Y = \\frac{1}{2}$ (trong số con đực gồm $\\frac{1}{2}X^W Y : \\frac{1}{2}X^w Y$). Vậy trong số ruồi đực, $B- X^W Y = \\frac{3}{4} \\times \\frac{1}{2} = \\frac{3}{8}$!"},{"id":"MCQ-MD-094","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Di truyền Tương tác 9:7","q":"Ở cây đậu thơm, màu hoa do 2 cặp gen PLĐL $(A,a)$ và $(B,b)$ tương tác bổ sung ($A-B-$ hoa đỏ; các kiểu gen còn lại hoa trắng). Cho cây hoa đỏ dị hợp 2 cặp gen ($AaBb$) tự thụ phấn thu được $F_1$. Lấy ngẫu nhiên một cây hoa ĐỎ ở $F_1$, xác suất để cây hoa đỏ này mang kiểu gen dị hợp cả 2 cặp gen ($AaBb$) là bao nhiêu?","opts":["$\\frac{2}{9}$.","$\\frac{1}{9}$.","$\\frac{1}{4}$.","$\\frac{4}{9}$."],"ans":3,"exp":"Trong $16$ tổ hợp $F_1$, nhóm hoa đỏ ($A-B-$) chiếm $9$ phần gồm: $1 AABB + 2 AABb + 2 AaBB + 4 AaBb$. Vậy trong số các cây hoa đỏ $F_1$, kiểu gen $AaBb$ chiếm $\\frac{4}{9}$."},{"id":"MCQ-MD-095","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Di truyền Tương tác 9:7","q":"Với cùng quy ước $A-B-$ hoa đỏ và các kiểu gen còn lại hoa trắng (PLĐL). Nếu lấy ngẫu nhiên $1$ cây hoa ĐỎ ở $F_1$ (thu được từ $AaBb \\times AaBb$) cho tự thụ phấn, xác suất ở đời $F_2$ thu được hoàn toàn $100\\%$ cây hoa đỏ (không xuất hiện hoa trắng) là:","opts":["$\\frac{2}{9}$.","$\\frac{4}{9}$.","$\\frac{1}{9}$.","$\\frac{1}{16}$."],"ans":2,"exp":"Trong nhóm hoa đỏ $F_1$ ($1AABB : 2AABb : 2AaBB : 4AaBb$), chỉ có cây đồng hợp $AABB$ (chiếm $\\frac{1}{9}$) khi tự thụ mới cho $100\\%$ hoa đỏ (các cây dị hợp 1 hoặc 2 cặp đều sinh ra hoa trắng)."},{"id":"MCQ-MD-096","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tương tác Cộng gộp & Số lớp KH","q":"Chiều cao của một loài cây do $4$ cặp gen $(Aa, Bb, Dd, Ee)$ nằm trên $4$ cặp NST khác nhau tương tác cộng gộp theo kiểu mỗi alen trội làm cây cao thêm $4\\text{ cm}$. Khi cho hai cây có kiểu gen đều dị hợp $4$ cặp gen lai với nhau ($AaBbDdEe \\times AaBbDdEe$), số kiểu hình chiều cao khác nhau tối đa và tỉ lệ kiểu hình giống cây cao nhất ($AABBDD EE$) lần lượt là:","opts":["$16$ loại kiểu hình và tỉ lệ cây cao nhất là $\\frac{1}{256}$.","$9$ loại kiểu hình và tỉ lệ cây cao nhất là $\\frac{70}{256}$.","$8$ loại kiểu hình và tỉ lệ cây cao nhất là $\\frac{1}{64}$.","$9$ loại kiểu hình và tỉ lệ cây cao nhất là $\\frac{1}{256}$."],"ans":3,"exp":"Có $4$ cặp dị hợp ($8$ vị trí alen), số alen trội trong kiểu gen con chạy từ $0$ đến $8$ (gồm $8 + 1 = 9$ mức kiểu hình). Cây cao nhất mang $8$ alen trội chiếm $(\\frac{1}{4})^4 = \\frac{1}{256}$."},{"id":"MCQ-MD-097","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Biện luận Quy luật 3 gen","q":"Cho phép lai phân tích $P: AaBbDd \\times aabbdd$ (mỗi gen quy định 1 tính trạng, trội hoàn toàn) thu được đời con $F_a$ chỉ có ĐÚNG $4$ kiểu hình với tỉ lệ $4 : 4 : 1 : 1$. Cách sắp xếp các gen trên nhiễm sắc thể phù hợp với kết quả trên là:","opts":["Cả $3$ cặp gen cùng nằm trên $1$ cặp NST, trong đó có $2$ cặp gen liên kết hoàn toàn với nhau và trao đổi chéo xảy ra ở khoảng giữa nhóm đó với cặp gen còn lại có tần số $f = 20\\%$.","$2$ cặp gen nằm trên $1$ cặp NST có HVG $20\\%$, cặp thứ 3 phân ly độc lập.","Cả $3$ cặp gen nằm trên $3$ cặp NST tương đồng khác nhau.","Cả $3$ cặp gen liên kết hoàn toàn tuyệt đối trên $1$ cặp NST."],"ans":0,"exp":"Nếu 2 gen trên 1 NST (HVG $20\\%$) và gen 3 PLĐL thì $F_a$ phải tạo $(0.4:0.4:0.1:0.1)(0.5:0.5)$ tức $8$ kiểu hình ($4:4:4:4:1:1:1:1$). Để $F_a$ chỉ có đúng $4$ kiểu hình $4:4:1:1$, cả 3 gen phải nằm trên cùng 1 NST, tạo 4 loại giao tử theo tỉ lệ $0.4 : 0.4 : 0.1 : 0.1$ ($f=20\\%$)."},{"id":"MCQ-MD-098","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thử nghiệm Đồng trội & Đa alen","q":"Ở thỏ, màu lông do 1 gen có 4 alen nằm trên NST thường quy định theo thứ tự trội hoàn toàn: $C$ (nâu đậm) $> c^{ch}$ (chinchilla) $> c^h$ (Himalaya) $> c$ (bạch tạng). Thực hiện phép lai giữa hai con thỏ $C c^h \\times c^{ch} c$. Tỉ lệ phân ly kiểu hình ở đời con là:","opts":["$3$ nâu đậm : $1$ bạch tạng.","$1$ nâu đậm : $1$ chinchilla : $1$ Himalaya : $1$ bạch tạng.","$2$ nâu đậm : $1$ chinchilla : $1$ bạch tạng.","$2$ nâu đậm : $1$ chinchilla : $1$ Himalaya."],"ans":3,"exp":"$Cc^h \\times c^{ch}c \\rightarrow 1 Cc^{ch}$ (nâu đậm) : $1 Cc$ (nâu đậm) : $1 c^{ch}c^h$ (chinchilla) : $1 c^h c$ (Himalaya) $\\Rightarrow 2:1:1$."},{"id":"MCQ-MD-099","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Di truyền Liên kết","q":"Ở một loài thực vật, alen $A$ (hoa đỏ) trội hoàn toàn so với $a$ (hoa trắng), $B$ (quả ngọt) trội hoàn toàn so với $b$ (quả chua). Hai cặp gen nằm trên cùng 1 NST và liên kết hoàn toàn. Cho cây $\\frac{AB}{ab}$ giao phấn với cây $\\frac{Ab}{aB}$. Tỉ lệ cá thể ở $F_1$ có kiểu hình hoa đỏ, quả ngọt nhưng có kiểu gen DỊ HỢP VỀ CẢ HAI CẶP GEN là bao nhiêu?","opts":["$0\\%$ (không có kiểu gen $\\frac{AB}{ab}$ hay $\\frac{Ab}{aB}$ nào ở $F_1$).","$25\\%$.","$50\\%$.","$12.5\\%$."],"ans":0,"exp":"$\\frac{AB}{ab}$ cho $\\underline{AB}, \\underline{ab}$; $\\frac{Ab}{aB}$ cho $\\underline{Ab}, \\underline{aB}$. Khi tổ hợp lại tạo $4$ kiểu gen: $\\frac{AB}{Ab}, \\frac{AB}{aB}, \\frac{Ab}{ab}, \\frac{aB}{ab}$ — tất cả đều chỉ dị hợp $1$ cặp gen (hoặc $1:2:1$ về KH), hoàn toàn không có kiểu gen dị hợp 2 cặp!"},{"id":"MCQ-MD-100","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Xác suất sinh con","q":"Ở người, bệnh bạch tạng do gen lặn $a$ trên NST thường quy định. Một cặp vợ chồng đều bình thường nhưng người chồng có chị gái bị bạch tạng, người vợ có em trai bị bạch tạng (bố mẹ hai bên đều bình thường). Xác suất để cặp vợ chồng này sinh ra một người con trai KHÔNG bị bệnh bạch tạng là bao nhiêu?","opts":["$\\frac{8}{9}$.","$\\frac{1}{18}$.","$\\frac{4}{9}$.","$\\frac{1}{9}$."],"ans":2,"exp":"Bố mẹ hai bên đều là $Aa \\times Aa$, nên chồng và vợ bình thường đều mang xác suất $(\\frac{1}{3}AA : \\frac{2}{3}Aa)$, mỗi người cho giao tử $a = \\frac{1}{3}$. XS con bị bệnh $= \\frac{1}{3} \\times \\frac{1}{3} = \\frac{1}{9} \\Rightarrow$ XS con không bị bệnh $= \\frac{8}{9}$. Nhân xác suất sinh con trai ($\\frac{1}{2}$): $\\frac{8}{9} \\times \\frac{1}{2} = \\frac{4}{9}$."},{"id":"MCQ-MD-101","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phép lai nhiều cặp gen","q":"Trong phép lai giữa hai cơ thể có kiểu gen $P: AaBbDdEe \\times aabbDdEe$ (các gen phân ly độc lập, trội hoàn toàn). Xác suất thu được cá thể ở đời $F_1$ mang ít nhất $3$ tính trạng trội là bao nhiêu?","opts":["$\\frac{9}{64}$.","$\\frac{33}{64}$.","$\\frac{21}{64}$.","$\\frac{27}{64}$."],"ans":1,"exp":"Liệt kê 2 trường hợp: $4$ trội ($\\frac{1}{2}\\cdot\\frac{1}{2}\\cdot\\frac{3}{4}\\cdot\\frac{3}{4} = \\frac{9}{64}$) và $3$ trội 1 lặn (lặn ở A: $\\frac{9}{64}$; lặn ở B: $\\frac{9}{64}$; lặn ở D: $\\frac{3}{64}$; lặn ở E: $\\frac{3}{64}$). Tổng xác suất $= \\frac{9 + 9 + 9 + 3 + 3}{64} = \\frac{33}{64}$."},{"id":"MCQ-MD-102","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Bản đồ Gen 2 điểm","q":"Xét một cơ thể có kiểu gen dị hợp $2$ cặp gen $\\frac{Ab}{aB}$ tiến hành giảm phân. Nếu trong giảm phân chỉ có $36\\%$ số tế bào sinh hạt phấn xảy ra trao đổi chéo tại $1$ điểm giữa $A$ và $B$, thì khi đem cơ thể này lai phân tích với $\\frac{ab}{ab}$, tỉ lệ kiểu hình ở đời con mang $2$ tính trạng trội ($A-B-$) là bao nhiêu?","opts":["$41\\%$.","$9\\%$.","$36\\%$.","$18\\%$."],"ans":1,"exp":"$36\\%$ tế bào có TĐC $\\Rightarrow f = \\frac{36\\%}{2} = 18\\%$. Do cơ thể là dị hợp chéo $\\frac{Ab}{aB}$, giao tử $\\underline{AB}$ là giao tử hoán vị chiếm $\\frac{18\\%}{2} = 9\\%$. Lai phân tích với $\\frac{ab}{ab}$ cho $A-B- = 9\\%$."},{"id":"MCQ-MD-103","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tương tác Át chế 12:3:1","q":"Ở bí ngô, màu quả tuân theo tương tác át chế trội $12:3:1$ ($W---$: trắng; $wwY-$: vàng; $wwyy$: xanh). Lai giữa hai cây bí ngô quả trắng dị hợp có kiểu gen $WwYy \\times Wwyy$. Tỉ lệ phân ly kiểu hình ở đời con là:","opts":["$12$ quả trắng : $3$ quả vàng : $1$ quả xanh.","$2$ quả trắng : $1$ quả vàng : $1$ quả xanh.","$6$ quả trắng : $1$ quả vàng : $1$ quả xanh.","$3$ quả trắng : $1$ quả vàng."],"ans":2,"exp":"$Ww \\times Ww \\rightarrow \\frac{3}{4}W- : \\frac{1}{4}ww$; $Yy \\times yy \\rightarrow \\frac{1}{2}Y- : \\frac{1}{2}yy$. Suy ra Trắng ($W---$) $= \\frac{3}{4} = \\frac{6}{8}$; Vàng ($wwY-$) $= \\frac{1}{4} \\times \\frac{1}{2} = \\frac{1}{8}$; Xanh ($wwyy$) $= \\frac{1}{4} \\times \\frac{1}{2} = \\frac{1}{8} \\Rightarrow 6:1:1$."},{"id":"MCQ-MD-104","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Gen liên kết giới tính","q":"Ở một loài bướm ($ZZ/ZW$), alen $A$ (cánh có đốm) trội hoàn toàn so với $a$ (cánh trơn) nằm trên vùng không tương đồng của NST Z. Phép lai nào sau đây tạo ra đời con $F_1$ có ĐÚNG $50\\%$ cá thể cánh có đốm ở giới đực và $50\\%$ cá thể cánh có đốm ở giới cái (tức mỗi giới đều phân ly $1:1$)?","opts":["$Z^A Z^a \\times Z^A W$.","$Z^A Z^a \\times Z^a W$.","$Z^A Z^A \\times Z^a W$.","$Z^a Z^a \\times Z^A W$."],"ans":1,"exp":"Khi lai $\\text{♂ } Z^A Z^a \\times \\text{♀ } Z^a W \\rightarrow \\frac{1}{4} Z^A Z^a$ (đực đốm) : $\\frac{1}{4} Z^a Z^a$ (đực trơn) : $\\frac{1}{4} Z^A W$ (cái đốm) : $\\frac{1}{4} Z^a W$ (cái trơn)."},{"id":"MCQ-MD-105","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Di truyền Tế bào chất","q":"Ở một loài thực vật giao phấn, cây mẹ mang đột biến lục lạp lốm đốm (có cả lục lạp xanh bình thường và lục lạp trắng đột biến không tổng hợp diệp lục trong tế bào). Khi lấy hạt phấn của cây lá xanh thuần chủng thụ phấn cho hoa mọc trên cành lá đốm của cây mẹ, đời con thu được có thể xuất hiện những loại kiểu hình nào?","opts":["Xuất hiện cả 3 loại kiểu hình (cây lá xanh, cây lá trắng và cây lá đốm) tùy thuộc vào việc tế bào trứng chứa toàn lục lạp xanh, toàn lục lạp trắng hay hỗn hợp cả hai loại lục lạp khi phân chia ngẫu nhiên tế bào chất.","Chắc chắn $100\\%$ cây con đều có lá đốm đồng đều.","Chắc chắn $100\\%$ cây con đều có lá xanh giống cây cho hạt phấn.","Chắc chắn phân ly đúng theo tỉ lệ $3$ lá xanh : $1$ lá trắng."],"ans":0,"exp":"Hiện tượng tế bào chất dị hợp (Heteroplasmy) ở cành đốm của <i>Mirabilis jalapa</i>: quá trình phân chia lục lạp vào tế bào trứng là ngẫu nhiên nên trứng có thể chỉ nhận lục lạp xanh, chỉ nhận lục lạp trắng hoặc cả hai."},{"id":"MCQ-MD-106","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phân ly Độc lập","q":"Cho phép lai $P: AaBbDd \\times AaBbDd$ (các gen PLĐL, trội hoàn toàn). Tính tỉ lệ cá thể ở $F_1$ có kiểu hình trội về tất cả các tính trạng ($A-B-D-$) nhưng KHÔNG thuần chủng (mang ít nhất 1 cặp gen dị hợp)?","opts":["$\\frac{26}{64}$ ($\\frac{13}{32}$).","$\\frac{27}{64}$.","$\\frac{8}{64}$.","$\\frac{1}{64}$."],"ans":0,"exp":"Tổng tỉ lệ $A-B-D- = (\\frac{3}{4})^3 = \\frac{27}{64}$. Trong đó thuần chủng $AABBDD = (\\frac{1}{4})^3 = \\frac{1}{64}$. Suy ra kiểu hình trội không thuần chủng $= \\frac{27}{64} - \\frac{1}{64} = \\frac{26}{64} = \\frac{13}{32}$."},{"id":"MCQ-MD-107","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hoán vị Gen & Số KG","q":"Trong phép lai giữa hai cây có kiểu gen $\\frac{AB}{ab} Dd \\times \\frac{Ab}{aB} dd$, biết có hoán vị gen giữa $A$ và $B$ ở cả hai giới. Nếu một học sinh muốn chọn ra ở $F_1$ tất cả các kiểu gen quy định kiểu hình $A-B-D-$, có tối đa bao nhiêu kiểu gen khác nhau thuộc kiểu hình này?","opts":["$9$ kiểu gen.","$4$ kiểu gen.","$10$ kiểu gen.","$5$ kiểu gen."],"ans":3,"exp":"Kiểu hình $A-B-$ trên 1 cặp NST luôn có tối đa $5$ loại kiểu gen: $\\frac{AB}{AB}, \\frac{AB}{Ab}, \\frac{AB}{aB}, \\frac{AB}{ab}, \\frac{Ab}{aB}$ (cả 5 loại đều xuất hiện khi 2 bên đều cho đủ 4 giao tử!). Cặp $Dd \\times dd$ chỉ có $1$ kiểu gen quy định $D-$ là $Dd$. Vậy tổng $= 5 \\times 1 = 5$ kiểu gen."},{"id":"MCQ-MD-108","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tương tác Gen & Át chế","q":"Ở một loài chim, màu lông do 2 cặp gen PLĐL quy định: cặp $(A,a)$ quyết định có tổng hợp sắc tố hay không ($A-$ tạo sắc tố, $aa$ không tạo sắc tố nên lông trắng); cặp $(B,b)$ quyết định dạng sắc tố ($B-$ lông xanh, $bb$ lông vàng trên nền có sắc tố $A-$). Lai chim lông xanh dị hợp $AaBb$ với chim lông trắng có kiểu gen $aaBb$. Tỉ lệ kiểu hình ở đời con thu được là:","opts":["$3$ xanh : $3$ vàng : $2$ trắng.","$3$ xanh : $1$ vàng : $4$ trắng.","$9$ xanh : $3$ vàng : $4$ trắng.","$1$ xanh : $1$ vàng : $2$ trắng."],"ans":1,"exp":"$Aa \\times aa \\rightarrow \\frac{1}{2}A- : \\frac{1}{2}aa$; $Bb \\times Bb \\rightarrow \\frac{3}{4}B- : \\frac{1}{4}bb$. Suy ra Xanh ($A-B-$) $= \\frac{1}{2}\\cdot\\frac{3}{4} = \\frac{3}{8}$; Vàng ($A-bb$) $= \\frac{1}{2}\\cdot\\frac{1}{4} = \\frac{1}{8}$; Trắng ($aa--$) $= \\frac{1}{2} = \\frac{4}{8} \\Rightarrow 3:1:4$."},{"id":"MCQ-MD-109","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hạn chế bởi giới tính","q":"Khác với tính trạng phụ thuộc giới tính (như hói đầu ở người: $Bb$ biểu hiện khác nhau ở nam và nữ), tính trạng <strong>Hạn chế bởi giới tính</strong> (Sex-limited trait) có đặc điểm nào sau đây?","opts":["Gen chỉ nằm trên nhiễm sắc thể Y và không có ở con cái.","Gen quy định nằm trên nhiễm sắc thể thường (hoặc giới tính) có ở cả hai giới, nhưng tính trạng CHỈ biểu hiện ra kiểu hình ở duy nhất một giới (ví dụ tính trạng sản lượng sữa cao ở bò cái hoặc bộ lông sặc sỡ ở gà trống) do phụ thuộc vào môi trường nội tiết/giới tính.","Tính trạng chỉ di truyền qua tế bào chất của trứng.","Con đực và con cái luôn biểu hiện kiểu hình giống hệt nhau $100\\%$."],"ans":1,"exp":"Con bò đực vẫn mang và truyền cho con gái các alen quy định năng suất sữa cao trên NST thường, dù bản thân bò đực không bao giờ tiết sữa ($0\\%$ penetrance ở đực) — đó là tính trạng hạn chế bởi giới tính."},{"id":"MCQ-MD-110","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tác động của Môi trường","q":"Ở người, bệnh rối loạn chuyển hóa Phenylketonuria (PKU) do gen lặn $a$ trên NST thường gây thiếu hụt enzyme chuyển hóa Phenylalanine, dẫn tới tích tụ acid phenylpyruvic gây tổn thương não và chậm phát triển trí tuệ nặng nếu ăn thức ăn bình thường. Tuy nhiên, nếu phát hiện sớm ngay sau sinh và áp dụng chế độ ăn kiêng nghèo Phenylalanine nghiêm ngặt, trẻ mang kiểu gen $aa$ vẫn phát triển trí tuệ hoàn toàn bình thường. Hiện tượng này chứng minh điều gì?","opts":["Bệnh PKU thực chất là bệnh truyền nhiễm chứ không do gen.","Trẻ sau khi ăn kiêng sẽ sinh con hoàn toàn không mang gen $a$.","Bệnh di truyền vẫn có thể điều chỉnh biểu hiện kiểu hình trong phạm vi mức phản ứng bằng cách can thiệp thay đổi yếu tố môi trường (dinh dưỡng), dù kiểu gen bệnh $aa$ vẫn giữ nguyên và vẫn di truyền cho thế hệ sau.","Chế độ ăn kiêng đã biến đổi gen lặn $a$ thành gen trội $A$ trong tế bào thần kinh."],"ans":2,"exp":"Kiểu hình là kết quả tương tác giữa Kiểu gen và Môi trường (Phenocopy/can thiệp dinh dưỡng): điều trị PKU không sửa DNA nhưng tránh cơ chất độc tích tụ giúp biểu hiện kiểu hình bình thường."},{"id":"MCQ-MD-111","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Kiểm định Phép lai","q":"Khi cho 2 cây hoa đỏ lai với nhau ($P$) thu được $F_1$ gồm $270$ cây hoa đỏ : $210$ cây hoa trắng. Rút gọn tỉ lệ $270 : 210$ ta được $9 : 7$. Để kiểm chứng chắc chắn đây là tương tác bổ sung $2$ cặp gen PLĐL chứ không phải hiện tượng khác, phép lai kiểm chứng đơn giản và trực tiếp nhất tiếp theo là gì?","opts":["Lấy 2 cây hoa trắng $F_1$ bất kỳ lai với nhau.","Nuôi cấy mô sẹo từ lá cây hoa đỏ.","Cho cây hoa đỏ $P$ tự thụ phấn thêm một lần nữa (sẽ lại ra $9:7$).","Lấy cây hoa đỏ $P$ đem lai phân tích với cây hoa trắng đồng hợp lặn ($aabb$); nếu đời con $F_a$ phân ly đúng tỉ lệ $1$ đỏ : $3$ trắng thì giả thuyết tương tác bổ sung $9:7$ được xác nhận."],"ans":3,"exp":"Lai phân tích $AaBb \\times aabb$ cho $1 AaBb$ (đỏ) : $1 Aabb + 1 aaBb + 1 aabb$ (3 trắng) là phép thử vàng phân biệt tỉ lệ tương tác $9:7$ ($1:3$) với các cơ chế khác."},{"id":"MCQ-MD-112","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phép lai nhiều cặp gen","q":"Cho phép lai $P: AaBb\\frac{DE}{de} \\times AaBb\\frac{De}{dE}$ (các gen trội hoàn toàn; tần số hoán vị gen giữa $D$ và $E$ ở cả 2 giới là $20\\%$). Tỉ lệ cá thể ở $F_1$ có kiểu hình mang cả $4$ tính trạng trội ($A-B-D-E-$) là:","opts":["$28.6875\\%$.","$30.375\\%$.","$27.000\\%$.","$31.500\\%$."],"ans":1,"exp":"$A-B- = \\frac{3}{4} \\times \\frac{3}{4} = \\frac{9}{16} = 0.5625$. Ở cặp liên kết: $\\underline{de}_1 = 0.4$; $\\underline{de}_2 = 0.1 \\Rightarrow ddee = 0.04 \\Rightarrow D-E- = 0.50 + 0.04 = 0.54$. Suy ra $A-B-D-E- = 0.5625 \\times 0.54 = 0.30375 = 30.375\\%$."},{"id":"MCQ-MD-113","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Số phép lai","q":"Xét $2$ cặp gen $(A, a)$ và $(B, b)$ phân ly độc lập, trội hoàn toàn. Nếu không phân biệt vai trò của bố và mẹ, có bao nhiêu phép lai khác nhau về kiểu gen cho đời con thu được tỉ lệ kiểu hình $3 : 1$?","opts":["$6$ phép lai.","$8$ phép lai.","$12$ phép lai.","$4$ phép lai."],"ans":1,"exp":"Để tích hai cặp ra $3:1 = (3:1) \\times 1$: nếu cặp $A$ cho $3:1$ ($Aa \\times Aa$: 1 kiểu) thì cặp $B$ cho $100\\%$ ($BB\\times BB, BB\\times Bb, BB\\times bb, bb\\times bb$: 4 kiểu) $\\Rightarrow 4$ phép lai. Ngược lại cặp $B$ cho $3:1$ và cặp $A$ đồng tính có $4$ phép lai nữa. Tổng cộng $8$ phép lai."},{"id":"MCQ-MD-114","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bản đồ Gen 3 Điểm & Nhiễu","q":"Ở ngô, 3 gen lặn trên NST số 9 quy định hạt có màu ($c$), hạt trơn ($sh$) và nội nhũ dẻo ($wx$), các alen kiểu dại tương ứng là $C, Sh, Wx$. Tiến hành lai phân tích cây dị hợp 3 cặp gen thu được 8 lớp kiểu hình với số liệu:<br>• $C\\text{ }Sh\\text{ }Wx$: $2708$ | $c\\text{ }sh\\text{ }wx$: $2538$<br>• $C\\text{ }sh\\text{ }wx$: $116$ | $c\\text{ }Sh\\text{ }Wx$: $113$<br>• $C\\text{ }Sh\\text{ }wx$: $601$ | $c\\text{ }sh\\text{ }Wx$: $626$<br>• $C\\text{ }sh\\text{ }Wx$: $4$ | $c\\text{ }Sh\\text{ }wx$: $2$<br>(Tổng số $6708$ cá thể). Trật tự sắp xếp của 3 gen trên NST và khoảng cách bản đồ $d(C-Sh)$ xấp xỉ là:","opts":["$C - Sh - Wx$ và $d(C-Sh) \\approx 18.4\\text{ cM}$.","$Sh - C - Wx$ và $d(C-Sh) \\approx 18.4\\text{ cM}$.","$C - Wx - Sh$ và $d(C-Sh) \\approx 3.5\\text{ cM}$.","$C - Sh - Wx$ và $d(C-Sh) \\approx 3.5\\text{ cM}$."],"ans":3,"exp":"Lớp bố mẹ đông nhất là $C\\text{ }Sh\\text{ }Wx$ và $c\\text{ }sh\\text{ }wx$ (kiểu gen dị hợp $\\frac{C\\text{ }Sh\\text{ }Wx}{c\\text{ }sh\\text{ }wx}$). Lớp TĐC kép hiếm nhất là $C\\text{ }sh\\text{ }Wx$ ($4$) và $c\\text{ }Sh\\text{ }wx$ ($2$), khác lớp bố mẹ đúng ở locus $Sh/sh \\Rightarrow$ Gen $Sh$ nằm Ở GIỮA ($C - Sh - Wx$). Khoảng cách $d(C-Sh) = \\frac{(116+113) + (4+2)}{6708} \\times 100 = \\frac{235}{6708} \\times 100 \\approx 3.50\\text{ cM}$."},{"id":"MCQ-MD-115","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bản đồ Gen 3 Điểm & Nhiễu","q":"Tiếp tục với số liệu thí nghiệm 3 gen ở ngô ($6708$ cá thể) có $d(C-Sh) = 3.50\\text{ cM}$, $d(Sh-Wx) = \\frac{601+626+6}{6708} \\times 100 = 18.38\\text{ cM}$ và tổng số cá thể trao đổi chéo kép thực tế là $4 + 2 = 6$ cá thể ($f_{\\text{kép thực tế}} = \\frac{6}{6708} \\approx 0.000894$). Giá trị Hệ số trùng hợp ($C$) và Độ nhiễu ($I$) trong đoạn NST này xấp xỉ là:","opts":["$C \\approx 1.39$ và $I \\approx -0.39$.","$C = 1.00$ và $I = 0.00$.","$C \\approx 0.86$ và $I \\approx 0.14$.","$C \\approx 0.14$ và $I \\approx 0.86$ (nhiễu dương rất mạnh — trao đổi chéo ở vùng 1 cản trở trao đổi chéo ở vùng kế bên)."],"ans":3,"exp":"$f_{\\text{kép lý thuyết}} = 0.035 \\times 0.1838 \\approx 0.00643$. Hệ số trùng hợp $C = \\frac{0.000894}{0.00643} \\approx 0.139 \\approx 0.14$. Độ nhiễu $I = 1 - C \\approx 0.86$."},{"id":"MCQ-MD-116","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bản đồ Tâm động Neurospora","q":"Ở nấm <i>Neurospora crassa</i>, xét gen $leu$ nằm cách tâm động một khoảng $14\\text{ cM}$. Nếu người ta kiểm tra ngẫu nhiên $1000$ nang bào tử (mỗi nang có 8 bào tử đơn bội xếp thẳng hàng theo thứ tự phân bào giảm phân - nguyên phân) từ phép lai $leu^+ \\times leu^-$, số nang có kiểu sắp xếp phân ly ở lần phân bào II (SDS: $2:2:2:2$ hoặc $2:4:2$) dự kiến thu được là bao nhiêu?","opts":["$70$ nang SDS.","$140$ nang SDS (và $860$ nang FDS $4:4$).","$560$ nang SDS.","$280$ nang SDS (và $720$ nang FDS $4:4$)."],"ans":3,"exp":"Áp dụng công thức bản đồ tâm động ở <i>Neurospora</i>: $d = \\frac{1}{2} \\times \\%\\text{SDS} \\Rightarrow \\%\\text{SDS} = 2d = 2 \\times 14\\% = 28\\%$. Trong $1000$ nang có $280$ nang SDS."},{"id":"MCQ-MD-117","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bản đồ Tâm động & 2 Gen Neurospora","q":"Ở nấm <i>Neurospora</i>, khi lai hai chủng đột biến $a^+ b^- \\times a^- b^+$ (trong đó hai gen $a$ và $b$ nằm trên HAI ĐỐI CÁNH KHÁC NHAU hay cùng cánh? Nếu kết quả các bộ tứ thu được chủ yếu là $PD$ (Lưỡng kiểu bố mẹ) $\\gg NPD$ (Lưỡng kiểu không bố mẹ) với rất ít $T$ (Tứ kiểu)), mối liên kết giữa hai gen $a$ và $b$ là:","opts":["Hai gen $a$ và $b$ nằm LIÊN KẾT GẦN NHAU trên cùng một nhiễm sắc thể (vì khi $PD \\gg NPD$, xác suất trao đổi chéo kép 4 sợi tạo $NPD$ rất hiếm).","Hai gen phân ly độc lập nằm trên hai nhiễm sắc thể khác nhau ($PD \\approx NPD$).","Hai gen nằm trong ty thể.","Hai gen nằm trên hai nhánh đối diện nhưng đều sát bên tâm động? Nếu hai gen PLĐL ở rất gần tâm động thì $PD = NPD$ và chỉ có $T \\approx 0$ chứ KHÔNG có $PD \\gg NPD$!"],"ans":0,"exp":"Trong phân tích bộ tứ nấm men/nấm sợi: Nếu 2 gen PLĐL thì $PD = NPD$ (do xếp hàng ngẫu nhiên kỳ giữa I). Chỉ khi 2 gen LIÊN KẾT trên cùng 1 NST mới cho $PD \\gg NPD$!"},{"id":"MCQ-MD-118","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Thử nghiệm Cis-Trans","q":"Phân lập $5$ dòng đột biến lặn độc lập ($m_1, m_2, m_3, m_4, m_5$) cùng gây kiểu hình mất khả năng tổng hợp sắc tố đỏ ở nấm men. Tiến hành lai các dòng với nhau tạo cá thể lưỡng bội dị hợp kép (*trans*):<br>• $(m_1 \\times m_2)$: Đỏ ($+$) ; $(m_1 \\times m_3)$: Trắng ($-$) ; $(m_1 \\times m_4)$: Đỏ ($+$) ; $(m_1 \\times m_5)$: Trắng ($-$).<br>• $(m_2 \\times m_4)$: Trắng ($-$) ; $(m_2 \\times m_3)$: Đỏ ($+$) ; $(m_3 \\times m_5)$: Trắng ($-$).<br>Năm đột biến này thuộc bao nhiêu gen (nhóm bổ sung) khác nhau?","opts":["$3$ gen khác nhau.","$1$ gen duy nhất.","$2$ gen khác nhau: Gen I gồm $(m_1, m_3, m_5)$ và Gen II gồm $(m_2, m_4)$.","$5$ gen khác nhau."],"ans":2,"exp":"Không bổ sung được ($-$) nghĩa là cùng nằm trên 1 gen: $(m_1, m_3, m_5)$ không bổ sung cho nhau ($-$) nên thuộc cùng 1 gen; $(m_2, m_4)$ không bổ sung cho nhau ($-$) nhưng đều bổ sung ($+$) với nhóm kia nên thuộc gen thứ 2."},{"id":"MCQ-MD-119","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Con đường Hóa sinh & Phả hệ","q":"Sự hình thành sắc tố vỏ ốc trải qua chuỗi chuyển hóa: Tiền chất không màu $\\xrightarrow{\\text{Gen } A}$ Vàng $\\xrightarrow{\\text{Gen } B}$ Nâu $\\xrightarrow{\\text{Gen } D}$ Đen (trong đó các alen trội $A, B, D$ tổng hợp enzyme có chức năng, các alen lặn $a, b, d$ mất chức năng và 3 gen PLĐL). Cho hai con ốc đều dị hợp 3 cặp gen ($AaBbDd \\times AaBbDd$) giao phối với nhau. Tỉ lệ vỏ ốc có màu VÀNG ở đời con là bao nhiêu?","opts":["$\\frac{27}{64}$.","$\\frac{1}{4}$.","$\\frac{3}{16}$ ($\\frac{12}{64}$).","$\\frac{9}{64}$."],"ans":2,"exp":"Để dừng lại ở sắc tố VÀNG, bước 1 phải chạy được ($A-$) và bước 2 bị tắc ($bb$), bất kể gen $D/d$ mang alen gì ($D-$ hay $dd$ cũng không có chất nâu làm cơ chất)! Vậy tỉ lệ vỏ vàng $= A-bb-- = \\frac{3}{4} \\times \\frac{1}{4} \\times 1 = \\frac{3}{16}$."},{"id":"MCQ-MD-120","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Con đường Hóa sinh","q":"Với cùng chuỗi hóa sinh: Không màu $\\xrightarrow{A}$ Vàng $\\xrightarrow{B}$ Nâu $\\xrightarrow{D}$ Đen (3 gen PLĐL), nhưng giả sử có thêm một gen thứ tư $E$ (PLĐL) mà alen trội $E$ ức chế hoàn toàn hoạt động của Enzyme B (còn $ee$ không ức chế). Khi cho cá thể dị hợp $4$ cặp gen ($AaBbDdEe$) tự thụ phấn, tỉ lệ kiểu hình màu ĐEN thu được là bao nhiêu?","opts":["$\\frac{9}{64}$.","$\\frac{27}{64}$.","$\\frac{81}{256}$.","$\\frac{27}{256}$."],"ans":3,"exp":"Để ra màu ĐEN, cả 3 enzyme A, B, D phải hoạt động ($A-B-D-$) ĐỒNG THỜI chất ức chế $E$ phải vắng mặt ($ee$). Vậy $A-B-D-ee = \\frac{3}{4} \\times \\frac{3}{4} \\times \\frac{3}{4} \\times \\frac{1}{4} = \\frac{27}{256}$."},{"id":"MCQ-MD-121","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Kiểm định Chi-square","q":"Khi lai hai giống đậu thuần chủng thu được $F_1$, cho $F_1$ tự thụ phấn thu được $F_2$ gồm $160$ cây với $96$ cây hoa đỏ : $64$ cây hoa trắng. Một học sinh giả thuyết đây là tương tác bổ sung tỉ lệ kỳ vọng $9 : 7$. Giá trị thống kê $\\chi^2 = \\sum \\frac{(O-E)^2}{E}$ tính được là bao nhiêu và kết luận ra sao (biết ngưỡng tra bảng ở mức ý nghĩa $0.05$ với bậc tự do $df=1$ là $\\chi^2_{0.05} = 3.84$)?","opts":["$\\chi^2 = 9.14 > 3.84 \\Rightarrow$ Bác bỏ giả thuyết $9:7$.","$\\chi^2 = 3.84 \\Rightarrow$ Bác bỏ giả thuyết.","$\\chi^2 = 0.00$ tuyệt đối.","$\\chi^2 = 0.914 < 3.84 \\Rightarrow$ CHẤP NHẬN giả thuyết tương tác bổ sung $9:7$ (sai khác chỉ do ngẫu nhiên mẫu)."],"ans":3,"exp":"Kỳ vọng $9:7$ trên $160$ cây: $E_{\\text{đỏ}} = 160 \\times \\frac{9}{16} = 90$; $E_{\\text{trắng}} = 160 \\times \\frac{7}{16} = 70$. $\\chi^2 = \\frac{(96-90)^2}{90} + \\frac{(64-70)^2}{70} = \\frac{36}{90} + \\frac{36}{70} = 0.4 + 0.514 = 0.914 < 3.84 \\Rightarrow$ Phù hợp với tỉ lệ $9:7$!"},{"id":"MCQ-MD-122","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Độ thấm & Độ biểu hiện","q":"Bệnh đa ngón tay (Polydactyly - thừa ngón tay/chân) ở người do một alen trội $P$ trên NST thường quy định, nhưng có độ thấm (Penetrance) không hoàn toàn bằng $70\\%$. Một người đàn ông bình thường nhưng có bố mắc bệnh đa ngón và bản thân người đàn ông đó thực chất mang kiểu gen dị hợp $Pp$ (nhưng không biểu hiện bệnh do $30\\%$ không thấm) kết hôn với một phụ nữ bình thường $pp$. Xác suất đứa con đầu lòng của họ BIỂU HIỆN thành kiểu hình đa ngón là bao nhiêu?","opts":["$35\\%$.","$15\\%$.","$70\\%$.","$50\\%$."],"ans":0,"exp":"Con có xác suất nhận alen $P$ tạo kiểu gen $Pp$ là $50\\% = 0.5$. Với độ thấm $70\\%$, xác suất biểu hiện kiểu hình đa ngón ở đứa con là $0.5 \\times 0.7 = 0.35 = 35\\%$."},{"id":"MCQ-MD-123","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hoán vị Gen + Giao tử bất thụ","q":"Ở một loài thực vật, alen $A$ (hoa đỏ) trội hoàn toàn so với $a$ (hoa trắng), $B$ (quả dài) trội hoàn toàn so với $b$ (quả tròn). Cho cây $P$ có kiểu gen $\\frac{AB}{ab}$ tự thụ phấn (có HVG ở cả 2 giới với tần số $f = 20\\%$). Biết mọi loại noãn đều thụ tinh bình thường, nhưng các hạt phấn mang kiểu gen $\\underline{ab}$ bị mất khả năng thụ tinh ($100\\%$ hạt phấn $\\underline{ab}$ chết, các hạt phấn khác thụ tinh bình thường). Tỉ lệ cây hoa trắng, quả tròn ($\\frac{ab}{ab}$) ở đời $F_1$ là:","opts":["$16\\%$.","$0\\%$.","$4\\%$.","$8\\%$."],"ans":1,"exp":"Để tạo $\\frac{ab}{ab}$ bắt buộc phải có sự kết hợp giữa noãn $\\underline{ab}$ và hạt phấn $\\underline{ab}$. Do $100\\%$ hạt phấn $\\underline{ab}$ không thể thụ tinh, tỉ lệ $\\frac{ab}{ab}$ ở $F_1$ chắc chắn bằng $0\\%$!"},{"id":"MCQ-MD-124","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hoán vị Gen + Hạt phấn chết","q":"Cho cây có kiểu gen $\\frac{AB}{ab}$ tự thụ phấn (hoán vị gen 2 giới với $f = 20\\%$, các gen trội hoàn toàn). Biết mọi loại noãn đều thụ tinh bình thường, nhưng $100\\%$ hạt phấn mang kiểu gen $\\underline{ab}$ bị bất thụ (các hạt phấn $\\underline{AB}, \\underline{Ab}, \\underline{aB}$ thụ tinh bình thường). Tỉ lệ kiểu hình mang $1$ tính trạng trội $A$ và $1$ tính trạng lặn $b$ ($A-bb$) ở đời con $F_1$ là:","opts":["$\\frac{1}{12}$ ($\\approx 8.33\\%$).","$4\\%$.","$\\frac{1}{6}$ ($\\approx 16.67\\%$).","$9\\%$."],"ans":0,"exp":"Noãn bình thường: $0.4\\underline{AB} : 0.4\\underline{ab} : 0.1\\underline{Ab} : 0.1\\underline{aB}$. Hạt phấn hữu thụ sau khi loại $0.4\\underline{ab}$: $\\frac{4}{6}\\underline{AB} : \\frac{1}{6}\\underline{Ab} : \\frac{1}{6}\\underline{aB}$. Cây $A-bb$ hình thành khi hạt phấn $\\underline{Ab}$ ($\\frac{1}{6}$) thụ tinh cho noãn $\\underline{Ab}$ ($0.1$) hoặc $\\underline{ab}$ ($0.4$) $\\Rightarrow (0.1 + 0.4) \\times \\frac{1}{6} = \\frac{1}{12}$."},{"id":"MCQ-MD-125","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hoán vị Gen & Giới tính trên X","q":"Ở ruồi giấm, hai gen $y$ (thân vàng) và $w$ (mắt trắng) cùng nằm trên vùng không tương đồng của NST X và cách nhau $1.5\\text{ cM}$ (các alen kiểu dại tương ứng là $Y$: thân xám, $W$: mắt đỏ). Cho ruồi cái dị hợp $\\frac{X^{YW}}{X^{yw}}$ lai với ruồi đực kiểu dại $X^{YW} Y$. Xác suất xuất hiện một con ruồi ĐỰC có kiểu hình thân vàng, mắt đỏ ($X^{yW} Y$) trong tổng số ruồi con $F_1$ là bao nhiêu?","opts":["$0.375\\%$.","$24.625\\%$.","$0.75\\%$.","$1.5\\%$."],"ans":0,"exp":"Từ ruồi mẹ $\\frac{X^{YW}}{X^{yw}}$ với $f = 1.5\\% = 0.015$: giao tử hoán vị $X^{yW} = \\frac{0.015}{2} = 0.0075 = 0.75\\%$. Kết hợp với tinh trùng $Y$ ($0.5$) của ruồi đực $\\Rightarrow$ Ruồi đực $X^{yW} Y = 0.0075 \\times 0.5 = 0.00375 = 0.375\\%$."},{"id":"MCQ-MD-126","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phân ly Độc lập + Gây chết","q":"Ở một loài chuột, gen $A$ (lông vàng) trội hoàn toàn so với $a$ (lông đen), nhưng $AA$ chết ở giai đoạn phôi; gen $B$ (đuôi xoăn) trội hoàn toàn so với $b$ (đuôi thẳng) và $BB$ cũng gây chết ở giai đoạn phôi (2 cặp gen phân ly độc lập). Thực hiện phép lai $P: AaBb \\times AaBb$. Trong số các cá thể chuột con $F_1$ sống sót đến khi sinh, tỉ lệ chuột có kiểu gen $AaBb$ chiếm bao nhiêu?","opts":["$\\frac{4}{9}$.","$\\frac{2}{9}$.","$\\frac{4}{16}$.","$\\frac{1}{4}$."],"ans":0,"exp":"Cặp $A$: sống sót gồm $\\frac{2}{3}Aa : \\frac{1}{3}aa$ (tỉ lệ sống $3/4$). Cặp $B$: sống sót gồm $\\frac{2}{3}Bb : \\frac{1}{3}bb$. Trong số con sống sót, tỉ lệ $AaBb = \\frac{2}{3} \\times \\frac{2}{3} = \\frac{4}{9}$."},{"id":"MCQ-MD-127","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Liên kết Gen & Gây chết","q":"Ở ruồi giấm, alen trội $D$ gây chết ở trạng thái đồng hợp $DD$ (cá thể $Dd$ có cánh dang rộng); alen trội $Cy$ gây chết ở trạng thái đồng hợp $CyCy$ (cá thể $Cycy$ có cánh cong). Biết hai gen này nằm trên cùng 1 cặp NST số 2 (liên kết hoàn toàn ở ruồi đực, và trong một dòng cân bằng gây chết kép 'Balanced lethal stock' kiểu gen $\\frac{D\\text{ }cy}{d\\text{ }Cy}$ không thể tạo sống kiểu gen đồng hợp $DD$ hay $CyCy$ khi tạp giao giữa các cá thể cùng dòng). Nếu giả sử KHÔNG có trao đổi chéo ở cả 2 giới trong phép lai $\\frac{D\\text{ }cy}{d\\text{ }Cy} \\times \\frac{D\\text{ }cy}{d\\text{ }Cy}$, tỉ lệ sống sót và kiểu hình đời con thu được là:","opts":["$75\\%$ hợp tử sống sót theo tỉ lệ $2:1$.","$50\\%$ hợp tử sống sót và $100\\%$ số sống sót đều giữ nguyên kiểu gen dị hợp kép $\\frac{D\\text{ }cy}{d\\text{ }Cy}$ giống hệt bố mẹ (cánh vừa dang rộng vừa cong).","$100\\%$ hợp tử đều chết ở giai đoạn phôi.","$25\\%$ hợp tử sống sót đều đồng hợp."],"ans":1,"exp":"Phép lai tạo $\\frac{1}{4} \\frac{D\\text{ }cy}{D\\text{ }cy}$ (chết vì $DD$), $\\frac{1}{4} \\frac{d\\text{ }Cy}{d\\text{ }Cy}$ (chết vì $CyCy$) và $\\frac{2}{4} \\frac{D\\text{ }cy}{d\\text{ }Cy}$ (sống sót!). Đây là kỹ thuật 'hệ gây chết cân bằng' kinh điển của Muller để duy trì dòng dị hợp thuần nhất qua hàng trăm thế hệ trong phòng thí nghiệm!"},{"id":"MCQ-MD-128","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tương tác Cộng gộp nhiều gen","q":"Ở một loài thực vật, tính trạng chiều cao cây do 3 cặp gen PLĐL $(Aa, Bb, Dd)$ quy định theo kiểu cộng gộp: cây $aabbdd$ cao $100\\text{ cm}$, mỗi alen trội làm cây cao thêm $10\\text{ cm}$. Khi cho cây có kiểu gen $AaBbDd$ giao phấn với cây $AAbbDd$, tỉ lệ cây con có chiều cao $140\\text{ cm}$ (mang đúng $4$ alen trội) thu được ở đời $F_1$ là bao nhiêu?","opts":["$\\frac{3}{16}$ ($18.75\\%$).","$\\frac{3}{8}$ ($37.5\\%$).","$\\frac{5}{16}$ ($31.25\\%$).","$\\frac{1}{4}$ ($25\\%$)."],"ans":3,"exp":"Từ $AAbbDd$, đời con chắc chắn nhận $1$ alen trội $A$ (và $0$ từ $bb$). $4$ vị trí còn lại gồm $A$ (từ $Aa$), $B$ (từ $Bb$), $D_1, D_2$ (từ $Dd \\times Dd$) đều cho tỉ lệ trội $= \\frac{1}{2}$. Để tổng bằng $4$ alen trội, 4 vị trí này phải đóng góp đúng $3$ alen trội: $\\frac{C^3_4}{2^4} = \\frac{4}{16} = \\frac{1}{4}$."},{"id":"MCQ-MD-129","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phép lai 3 điểm & Hoán vị","q":"Một cơ thể thực vật có kiểu gen $\\frac{ABD}{abd}$ (3 gen liên kết theo đúng thứ tự $A - B - D$), trong đó khoảng cách $d(A-B) = 20\\text{ cM}$, $d(B-D) = 15\\text{ cM}$ và hệ số trùng hợp $C = 0.8$. Tỉ lệ các giao tử trao đổi chéo ĐƠN tại vùng $B - D$ (gồm $\\underline{ABd}$ và $\\underline{abD}$) của cơ thể này là:","opts":["$\\underline{ABd} = \\underline{abD} = 7.5\\%$ (tổng $15.0\\%$).","$\\underline{ABd} = \\underline{abD} = 1.2\\%$ (tổng $2.4\\%$).","$\\underline{ABd} = \\underline{abD} = 8.7\\%$ (tổng $17.4\\%$).","$\\underline{ABd} = \\underline{abD} = 6.3\\%$ (tổng $12.6\\%$)."],"ans":3,"exp":"$f_{\\text{kép}} = C \\cdot f_1 \\cdot f_2 = 0.8 \\times 0.20 \\times 0.15 = 0.024 = 2.4\\%$. Do đó $f_{\\text{đơn (B-D)}} = d(B-D) - f_{\\text{kép}} = 15\\% - 2.4\\% = 12.6\\%$, chia đều cho 2 giao tử $\\underline{ABd} = \\underline{abD} = 6.3\\%$."},{"id":"MCQ-MD-130","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Biện luận Tương tác + Hoán vị","q":"Ở một loài thực vật, màu hoa do 2 cặp gen $(A, a)$ và $(B, b)$ tương tác bổ sung ($A-B-$ hoa đỏ; các kiểu gen khác hoa trắng); chiều cao cây do cặp $(D, d)$ quy định ($D-$ thân cao, $dd$ thân thấp). Cho cây dị hợp 3 cặp gen tự thụ phấn thu được $F_1$ gồm: $49.5\\%$ cao đỏ : $6.75\\%$ thấp đỏ : $25.5\\%$ cao trắng : $18.25\\%$ thấp trắng. Kiểu gen của cây $P$ và tần số hoán vị gen ($f$) là:","opts":["$Aa\\frac{BD}{bd}$ (hoặc $Bb\\frac{AD}{ad}$) và $f = 20\\%$.","$Aa\\frac{BD}{bd}$ và $f = 40\\%$.","$Aa\\frac{Bd}{bD}$ và $f = 40\\%$.","$Aa\\frac{Bd}{bD}$ và $f = 20\\%$."],"ans":0,"exp":"Tỉ lệ $F_1$ có Cao/Thấp $= 3:1$ và Đỏ/Trắng $= 9:7$, nhưng $A-B-dd = 6.75\\% \\ne 0.5625 \\times 0.25 \\Rightarrow$ 1 gen màu hoa liên kết với $D$. Ta có $\\frac{3}{4}A- \\times (B-dd) = 0.0675 \\Rightarrow B-dd = 0.09 \\Rightarrow bbdd = 0.25 - 0.09 = 0.16 \\Rightarrow \\underline{bd} = 0.4 \\Rightarrow$ kiểu gen $Aa\\frac{BD}{bd}$ với $f = 20\\%$."},{"id":"MCQ-MD-131","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền Liên kết X-Y","q":"Ở một loài cá, gen quy định vảy đốm nằm trên vùng TƯƠNG ĐỒNG của cả hai NST giới tính X và Y ($A$: vảy có đốm trội hoàn toàn so với $a$: vảy trơn). Một nhà chọn giống cho lai cá cái vảy trơn ($X^a X^a$) với cá đực vảy có đốm thuần chủng tạo $F_1$, rồi chọn cá đực $F_1$ lai với cá cái $F_1$ thu được $F_2$ có tỉ lệ: toàn bộ cá đực đều vảy có đốm, còn cá cái phân ly $1$ vảy có đốm : $1$ vảy trơn. Kết luận đúng nhất về kiểu gen của cá đực ban đầu và cá đực $F_1$ là:","opts":["Cá đực $P$ có kiểu gen $X^A Y^a$ và cá đực $F_1$ có kiểu gen $X^a Y^a$.","Cá đực $P$ có kiểu gen $X^A Y^A$ và cá đực $F_1$ có kiểu gen $X^a Y^A$ (hoặc trong phép lai $F_1 \\times F_1$ có $X^A X^a \\times X^a Y^A$).","Gen này nằm trên vùng không tương đồng của NST X.","Gen này nằm trên vùng không tương đồng của NST Y."],"ans":1,"exp":"Cá cái vảy trơn $X^a X^a \\times$ cá đực thuần chủng $X^A Y^A \\rightarrow F_1$: $X^A X^a$ (cái) và $X^a Y^A$ (đực). Cho $F_1 \\times F_1 \\rightarrow F_2$: cái ($X^A X^a : X^a X^a = 1$ đốm : $1$ trơn) và đực ($X^A Y^A : X^a Y^A = 100\\%$ đốm)."},{"id":"MCQ-MD-132","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phép lai 3 điểm & Chọn lọc","q":"Một cá thể có kiểu gen $\\frac{ABD}{abd}$ (thứ tự $A-B-D$, khoảng cách $d(A-B) = 20\\text{ cM}$, $d(B-D) = 30\\text{ cM}$, không có hiện tượng nhiễu $I = 0$) tiến hành giảm phân. Tỉ lệ loại giao tử tái tổ hợp mang cả 3 alen có nguồn gốc hỗn hợp $\\underline{aBD}$ và $\\underline{AbD}$ lần lượt là:","opts":["$\\underline{aBD} = 14\\%$ và $\\underline{AbD} = 6\\%$.","$\\underline{aBD} = 10\\%$ và $\\underline{AbD} = 6\\%$.","$\\underline{aBD} = 8.5\\%$ và $\\underline{AbD} = 3\\%$.","$\\underline{aBD} = 7\\%$ và $\\underline{AbD} = 3\\%$."],"ans":3,"exp":"Không nhiễu ($I=0 \\Rightarrow C=1$): $f_{\\text{kép}} = 0.20 \\times 0.30 = 0.06 = 6\\%$ (chia đôi cho $\\underline{AbD}$ và $\\underline{aBd} \\Rightarrow \\underline{AbD} = 3\\%$). $f_{\\text{đơn (A-B)}} = 20\\% - 6\\% = 14\\%$ (chia đôi cho $\\underline{Abd}$ và $\\underline{aBD} \\Rightarrow \\underline{aBD} = 7\\%$)."},{"id":"MCQ-MD-133","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền Liên kết & 4 tính trạng","q":"Cho phép lai $P: \\frac{AB}{ab} \\frac{DE}{de} \\times \\frac{AB}{ab} \\frac{DE}{de}$ (các gen trội hoàn toàn, hai cặp NST khác nhau; cả hai giới đều có HVG giữa $A-B$ với $f_1 = 20\\%$ và giữa $D-E$ với $f_2 = 40\\%$). Tỉ lệ kiểu hình mang đồng thời cả 4 tính trạng trội ($A-B-D-E-$) ở đời $F_1$ là:","opts":["$38.94\\%$.","$31.50\\%$.","$32.64\\%$.","$40.96\\%$."],"ans":0,"exp":"Cặp 1 ($\\frac{AB}{ab}$, $f_1=20\\% \\Rightarrow \\underline{ab}=0.4$): $aabb = 0.16 \\Rightarrow A-B- = 0.50 + 0.16 = 0.66$. Cặp 2 ($\\frac{DE}{de}$, $f_2=40\\% \\Rightarrow \\underline{de}=0.3$): $ddee = 0.09 \\Rightarrow D-E- = 0.50 + 0.09 = 0.59$. Suy ra $A-B-D-E- = 0.66 \\times 0.59 = 0.3894 = 38.94\\%$."},{"id":"MCQ-MD-134","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền Tính trạng Khảm & X","q":"Bệnh loạn dưỡng cơ Duchenne (DMD) do đột biến gen lặn trên NST X quy định. Hầu hết phụ nữ mang gen dị hợp tử ($X^D X^d$) đều hoàn toàn khỏe mạnh, nhưng thỉnh thoảng người ta bắt gặp một phụ nữ mang kiểu gen dị hợp tử $X^D X^d$ vẫn có biểu hiện yếu cơ nhẹ hoặc nặng giống bệnh nhân nam. Cơ chế di truyền - tế bào nào giải thích hợp lý nhất cho trường hợp ngoại lệ này?","opts":["Hiện tượng bất hoạt NST X lệch ngẫu nhiên (Skewed X-inactivation): phần lớn tế bào cơ của người phụ nữ này tình cờ bất hoạt chiếc NST $X^D$ mang alen lành và giữ chiếc $X^d$ mang alen bệnh hoạt động.","Do đột biến chuyển đoạn làm gen Dystrophin nhảy sang NST Y.","Do gen Dystrophin nằm trong DNA ti thể.","Người phụ nữ đó thực chất mang bộ NST $XYY$."],"ans":0,"exp":"Do bất hoạt NST X ở phôi nang sớm diễn ra ngẫu nhiên trên một số lượng tế bào tiền thân có hạn, đôi khi tỉ lệ tế bào bất hoạt $X^D$ lên tới $80-95\\%$, khiến người nữ dị hợp ('manifesting carrier') biểu hiện triệu chứng bệnh."},{"id":"MCQ-MD-135","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phân ly & Tự thụ phấn","q":"Ở một loài thực vật, gen $A$ (hoa đỏ) trội hoàn toàn so với $a$ (hoa trắng). Xuất phát từ một cây hoa đỏ có kiểu gen $Aa$, qua $3$ thế hệ tự thụ phấn liên tiếp (thu được $F_3$). Nếu lấy tất cả các cây hoa ĐỎ ở thế hệ $F_3$ đem lai phân tích với cây hoa trắng ($aa$), tỉ lệ cây hoa trắng thu được ở đời con là bao nhiêu?","opts":["$\\frac{1}{16}$.","$\\frac{1}{18}$.","$\\frac{1}{8}$.","$\\frac{1}{9}$."],"ans":3,"exp":"Từ $Aa$ tự thụ $3$ thế hệ: $Aa_{F3} = (\\frac{1}{2})^3 = \\frac{1}{8}$; $AA_{F3} = \\frac{1 - 1/8}{2} = \\frac{7}{16}$; $aa_{F3} = \\frac{7}{16}$. Trong số các cây hoa ĐỎ ở $F_3$ ($\\frac{7}{16}AA : \\frac{2}{16}Aa = 7 AA : 2 Aa$), tỉ lệ cho giao tử $a = \\frac{2}{9} \\times \\frac{1}{2} = \\frac{1}{9}$. Lai với $aa$ tạo $\\frac{1}{9}$ hoa trắng!"},{"id":"MCQ-MD-136","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Biện luận Phép lai P","q":"Khi lai hai dòng cây hoa trắng thuần chủng khác nhau thu được $F_1$ gồm $100\\%$ cây hoa đỏ. Cho $F_1$ giao phấn với một cây hoa trắng có kiểu gen $Aabb$, đời con thu được tỉ lệ $3$ hoa đỏ : $5$ hoa trắng. Nếu đem $F_1$ tự thụ phấn thì tỉ lệ kiểu hình ở đời $F_2$ là bao nhiêu?","opts":["$9$ hoa đỏ : $7$ hoa trắng.","$9$ hoa đỏ : $6$ hoa hồng : $1$ hoa trắng.","$13$ hoa trắng : $3$ hoa đỏ.","$3$ hoa đỏ : $1$ hoa trắng."],"ans":0,"exp":"Hai dòng hoa trắng thuần chủng lai ra $100\\%$ hoa đỏ $\\Rightarrow F_1$ dị hợp $2$ cặp gen bổ sung ($AaBb$). Kiểm tra $AaBb \\times Aabb$: $A- = \\frac{3}{4}$, $B- = \\frac{1}{2} \\Rightarrow A-B-$ (đỏ) $= \\frac{3}{4} \\times \\frac{1}{2} = \\frac{3}{8}$; còn lại trắng $= \\frac{5}{8}$ (đúng $3:5$!). Vậy khi $F_1$ ($AaBb$) tự thụ thu được $9$ đỏ : $7$ trắng."},{"id":"MCQ-MD-137","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tương tác & Chuyển hóa sắc tố","q":"Ở một loài côn trùng, màu mắt do 2 gen PLĐL: gen $A$ tổng hợp enzyme chuyển sắc tố không màu $\\rightarrow$ đỏ; gen $B$ tổng hợp enzyme chuyển sắc tố không màu $\\rightarrow$ nâu (hai con đường song song độc lập: có cả sắc tố đỏ và nâu tạo mắt kiểu dại màu đỏ sẫm; chỉ có sắc tố đỏ tạo mắt đỏ tươi; chỉ có sắc tố nâu tạo mắt nâu; không có sắc tố nào tạo mắt trắng). Phép lai $P: AaBb \\times aaBb$ tạo ra tỉ lệ kiểu hình mắt ở $F_1$ là:","opts":["$1$ đỏ sẫm : $1$ đỏ tươi : $1$ nâu : $1$ trắng.","$9$ đỏ sẫm : $3$ đỏ tươi : $3$ nâu : $1$ trắng.","$3$ đỏ sẫm : $1$ đỏ tươi : $3$ nâu : $1$ trắng.","$3$ đỏ sẫm : $3$ đỏ tươi : $2$ trắng."],"ans":2,"exp":"$Aa \\times aa \\rightarrow \\frac{1}{2}A- : \\frac{1}{2}aa$; $Bb \\times Bb \\rightarrow \\frac{3}{4}B- : \\frac{1}{4}bb$. Suy ra: Đỏ sẫm ($A-B-$) $= \\frac{3}{8}$; Đỏ tươi ($A-bb$) $= \\frac{1}{8}$; Nâu ($aaB-$) $= \\frac{3}{8}$; Trắng ($aabb$) $= \\frac{1}{8} \\Rightarrow 3:1:3:1$."},{"id":"MCQ-MD-138","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"HVG & Tỉ lệ kiểu gen","q":"Thực hiện phép lai $P: \\frac{AB}{ab} \\times \\frac{Ab}{aB}$, biết hai gen liên kết với tần số hoán vị gen ở cả 2 giới là $f = 20\\%$. Tổng tỉ lệ cá thể ở đời con $F_1$ có kiểu gen <strong>dị hợp về đúng $1$ cặp gen</strong> là bao nhiêu?","opts":["$16\\%$.","$50\\%$.","$32\\%$.","$68\\%$."],"ans":3,"exp":"Cơ thể $\\frac{AB}{ab}$ ($0.4:0.4:0.1:0.1$) $\\times$ $\\frac{Ab}{aB}$ ($0.1:0.1:0.4:0.4$). Các kiểu gen dị hợp 1 cặp gồm $\\frac{AB}{Ab}, \\frac{AB}{aB}, \\frac{Ab}{ab}, \\frac{aB}{ab}$, mỗi loại có tỉ lệ $(0.4 \\times 0.4 + 0.1 \\times 0.1) = 0.17$. Tổng $= 4 \\times 0.17 = 68\\%$ (hoặc $1 - 16\\%\\text{ đồng hợp 2 cặp} - 16\\%\\text{ dị hợp 2 cặp} = 68\\%$)."},{"id":"MCQ-MD-139","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền Liên kết X & HVG","q":"Ở ruồi giấm, hai gen $A$ (mắt đỏ) trội hoàn toàn so với $a$ (mắt lựu) và $B$ (thân xám) trội hoàn toàn so với $b$ (thân vàng) cùng nằm trên vùng không tương đồng của NST X với tần số hoán vị gen $f = 16\\%$. Cho ruồi cái dị hợp $X^{AB} X^{ab}$ lai với ruồi đực $X^{Ab} Y$. Tỉ lệ ruồi con ở $F_1$ mang kiểu hình mắt đỏ, thân xám ($A-B-$) là bao nhiêu?","opts":["$21\\%$.","$42\\%$.","$50\\%$.","$46\\%$."],"ans":3,"exp":"Trứng từ ruồi cái ($f=16\\%$): $0.42\\text{ }X^{AB} : 0.42\\text{ }X^{ab} : 0.08\\text{ }X^{Ab} : 0.08\\text{ }X^{aB}$. Tinh trùng bố: $0.5\\text{ }X^{Ab} : 0.5\\text{ }Y$. Con cái $A-B-$ nhận $X^{Ab}$ kết hợp $X^{AB}$ hoặc $X^{aB}$ $= 0.5(0.42 + 0.08) = 25\\%$; con đực $A-B-$ nhận $Y$ kết hợp $X^{AB}$ $= 0.5 \\times 0.42 = 21\\%$. Tổng $= 46\\%$."},{"id":"MCQ-MD-140","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phân biệt Di truyền & Mẹ","q":"Ở một loài bướm, màu sắc vỏ kén do 1 gen trên NST thường quy định theo hiệu ứng dòng mẹ ($K$: kén vàng trội hoàn toàn so với $k$: kén trắng). Tuy nhiên, một gen khác trên NST thường là $M$ (cần thiết để tổng hợp tiền chất sắc tố trong cơ thể con, trội hoàn toàn so với $m$: không tạo tiền chất nên con $mm$ luôn kén trắng bất kể kiểu gen của mẹ là gì; còn con $M-$ biểu hiện màu kén vàng nếu mẹ có ít nhất 1 alen $K$). Cho bướm cái có kiểu gen $kkMM$ lai với bướm đực có kiểu gen $KKmm$ thu được $F_1$, rồi cho các cá thể $F_1$ giao phối với nhau thu $F_2$. Tỉ lệ kiểu hình ở $F_1$ và $F_2$ lần lượt là:","opts":["$F_1$: $100\\%$ kén vàng; $F_2$: $9$ vàng : $7$ trắng.","$F_1$: $3$ vàng : $1$ trắng; $F_2$: $3$ vàng : $1$ trắng.","$F_1$: $100\\%$ kén trắng (theo $kk$ của mẹ); $F_2$: $3$ kén vàng : $1$ kén trắng (do tất cả mẹ $F_1$ là $Kk$ nhưng $25\\%$ con $F_2$ là $mm$ không có tiền chất nên trắng).","$F_1$: $100\\%$ kén trắng; $F_2$: $100\\%$ kén vàng."],"ans":2,"exp":"Con $F_1$ là $100\\%\\text{ }KkMm$: do mẹ là $kk$ nên mọi con $F_1$ đều kén trắng. Khi $F_1$ ($KkMm$) giao phối tạo $F_2$: tất cả mẹ $F_1$ đều mang $K$ ($Kk$) nên mRNA $K$ có sẵn trong trứng, lúc này màu kén $F_2$ phụ thuộc kiểu gen cặp $M/m$ của chính con $F_2$ ($\\frac{3}{4} M-$ vàng : $\\frac{1}{4} mm$ trắng)!"},{"id":"MCQ-MD-141","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền Liên kết 2 giới","q":"Ở một loài thực vật, xét phép lai $P: \\frac{AB}{ab} \\times \\frac{Ab}{aB}$ thu được $F_1$ có số cá thể mang kiểu hình lặn về cả hai tính trạng ($\\frac{ab}{ab}$) chiếm $6\\%$. Biết hoán vị gen xảy ra ở cả 2 giới với tần số bằng nhau. Tỉ lệ kiểu hình mang 2 tính trạng trội có kiểu gen thuần chủng ($\\frac{AB}{AB}$) ở đời $F_1$ là bao nhiêu?","opts":["$4\\%$.","$12\\%$.","$9\\%$.","$6\\%$."],"ans":3,"exp":"Đặt tần số giao tử $\\underline{ab}$ của $\\frac{AB}{ab}$ là $x$ ($x \\ge 0.25$), thì của $\\frac{Ab}{aB}$ là $0.5 - x$. Ta có $x(0.5 - x) = 0.06 \\Rightarrow x = 0.3$ ($f = 40\\%$). Vì trong cả hai cơ thể $\\underline{AB} = \\underline{ab}$, nên $\\frac{AB}{AB} = \\underline{AB}_1 \\cdot \\underline{AB}_2 = x(0.5 - x) = 6\\%$!"},{"id":"MCQ-MD-142","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền Liên kết 3 gen","q":"Lai phân tích cá thể cái dị hợp 3 cặp gen ($Aa, Bb, Dd$) liên kết trên cùng 1 NST thu được 8 lớp kiểu hình: $ABD = abd = 35\\%$; $Abd = aBD = 10\\%$; $ABd = abD = 4\\%$; $AbD = aBd = 1\\%$. Khoảng cách bản đồ di truyền cộng dồn giữa hai gen ngoài cùng ($d_{1-2} + d_{2-3}$) bằng bao nhiêu cM?","opts":["$20\\text{ cM}$.","$28\\text{ cM}$.","$30\\text{ cM}$.","$32\\text{ cM}$ (với thứ tự $A - B - D$: $d(A-B) = 22\\text{ cM}$, $d(B-D) = 10\\text{ cM}$)."],"ans":3,"exp":"Lớp bố mẹ $ABD, abd$ ($70\\%$); lớp kép hiếm nhất $AbD, aBd$ ($2\\%$) đổi vị trí gen $B$ nên $B$ nằm giữa ($A-B-D$). Khoảng cách $d(A-B) = (10\\%+10\\%) + 2\\% = 22\\text{ cM}$; $d(B-D) = (4\\%+4\\%) + 2\\% = 10\\text{ cM}$. Tổng khoảng cách bản đồ cộng dồn $= 22 + 10 = 32\\text{ cM}$ (trong đó tỉ lệ tái tổ hợp quan sát trực tiếp giữa A và D là $28\\%$ do bỏ sót kép)."},{"id":"MCQ-MD-143","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Mức độ Hoán vị & Khoảng cách","q":"Tại sao khi hai gen nằm cách xa nhau trên cùng một nhiễm sắc thể (ví dụ cách nhau $60\\text{ cM}$), phép lai phân tích kiểm tra trực tiếp 2 gen đó chỉ đo được tần số tái tổ hợp quan sát tối đa dưới $50\\%$, khiến người ta phải dùng bản đồ 3 điểm (hoặc cộng dồn các khoảng ngắn liên tiếp) để đo khoảng cách thực trên $50\\text{ cM}$?","opts":["Vì ở khoảng cách xa, xác suất xảy ra các trao đổi chéo KÉP (số chẵn lần trao đổi chéo giữa 2 gen) tăng cao; trao đổi chéo kép khôi phục lại tổ hợp alen bố mẹ ban đầu ở 2 đầu mút nên làm tổng tần số tái tổ hợp quan sát luôn $\\le 50\\%$.","Vì các gen cách nhau trên $50\\text{ cM}$ tự động tách khỏi NST.","Vì enzyme ligase hàn gắn ngược các đoạn hoán vị.","Vì ở khoảng cách xa không bao giờ xảy ra trao đổi chéo đơn."],"ans":0,"exp":"Hàm ánh xạ Haldane chỉ ra rằng trao đổi chéo kép (hoặc chẵn lần) giữ nguyên cấu hình hai locus đầu cuối như ban đầu (không tái tổ hợp), làm tần số tái tổ hợp tiệm cận $50\\%$ khi khoảng cách bản đồ $d \\to \\infty$."},{"id":"MCQ-MD-144","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tương tác + Hoán vị 2 giới","q":"Ở một loài thực vật, màu hoa do 2 cặp gen $(A, a)$ và $(B, b)$ tương tác: $A-B-$ hoa đỏ; $A-bb$ và $aaB-$ hoa vàng; $aabb$ hoa trắng; đồng thời gen $B$ liên kết với gen $D$ quy định chiều cao ($D-$ thân cao, $dd$ thân thấp). Cho cây $Aa\\frac{BD}{bd}$ tự thụ phấn, ở $F_1$ thu được tỉ lệ cây thân thấp hoa trắng ($aa\\frac{bd}{bd}$) chiếm $2.25\\%$. Tỉ lệ cây thân CAO hoa ĐỎ ($A-B-D-$) ở đời $F_1$ là bao nhiêu?","opts":["$51.75\\%$.","$49.50\\%$.","$38.25\\%$.","$44.25\\%$."],"ans":3,"exp":"Từ $aa\\frac{bd}{bd} = \\frac{1}{4} aa \\times bbdd = 2.25\\% \\Rightarrow bbdd = 9\\%$. Suy ra $B-D- = 50\\% + 9\\% = 59\\%$. Với $Aa \\times Aa \\rightarrow A- = 75\\%$. Vậy $A-B-D- = 0.75 \\times 0.59 = 0.4425 = 44.25\\%$."},{"id":"MCQ-MD-145","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phép lai Thú & NST giới tính","q":"Ở một loài thú ($XX/XY$), tính trạng màu lông do 2 cặp gen phân ly độc lập: gen $A$ (lông đen) trội hoàn toàn so với $a$ (lông trắng) nằm trên NST thường; gen $B$ quy định tổng hợp melanin trội hoàn toàn so với $b$ (không tổng hợp melanin nên luôn cho lông trắng át chế $A$) nằm trên vùng không tương đồng của NST X. Phép lai $P: \\text{♀ } Aa X^B X^b \\times \\text{♂ } Aa X^b Y$. Tỉ lệ con ĐỰC có lông TRẮNG thu được trong tổng số con đời $F_1$ là bao nhiêu?","opts":["$18.75\\%$ ($\\frac{3}{16}$).","$25.00\\%$ ($\\frac{4}{16}$).","$31.25\\%$ ($\\frac{5}{16}$).","$37.50\\%$ ($\\frac{6}{16}$)."],"ans":2,"exp":"Con đực ($XY$) chiếm $\\frac{1}{2}$ tổng số con, chia thành $\\frac{1}{4} X^B Y : \\frac{1}{4} X^b Y$. Trong nhóm đực $X^b Y$ ($\\frac{1}{4}$ tổng số con): $100\\%$ lông trắng (do thiếu $B$). Trong nhóm đực $X^B Y$ ($\\frac{1}{4}$ tổng số con): chỉ $aa$ ($\\frac{1}{4}$) mới lông trắng $= \\frac{1}{4} \\times \\frac{1}{4} = \\frac{1}{16}$. Vậy con đực lông trắng trong tổng số con $F_1 = \\frac{1}{4} + \\frac{1}{16} = \\frac{5}{16} = 31.25\\%$!"},{"id":"MCQ-MD-146","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền ở Người & Phả hệ nhanh","q":"Ở người, bệnh mù màu do gen lặn $m$ trên NST X quy định, bệnh bạch tạng do gen lặn $a$ trên NST thường quy định. Một người phụ nữ có kiểu hình bình thường mang kiểu gen dị hợp cả 2 cặp gen ($Aa X^M X^m$) kết hôn với một người đàn ông bình thường nhưng có mẹ bị bạch tạng ($Aa X^M Y$). Xác suất họ sinh được một đứa con GÁI hoàn toàn bình thường (không mắc cả 2 bệnh) là:","opts":["$\\frac{9}{16}$ ($56.25\\%$).","$\\frac{3}{16}$ ($18.75\\%$).","$\\frac{3}{8}$ ($37.5\\%$).","$\\frac{9}{32}$ ($28.125\\%$)."],"ans":2,"exp":"Phép lai $Aa X^M X^m \\times Aa X^M Y$: Cặp NST thường cho $A- = \\frac{3}{4}$. Cặp giới tính sinh con gái bình thường ($X^M X^M + X^M X^m$, vì bố truyền $X^M$ cho $100\\%$ con gái!) $= \\frac{1}{2}$. Vậy xác suất sinh con gái không mắc cả 2 bệnh $= \\frac{3}{4} \\times \\frac{1}{2} = \\frac{3}{8} = 37.5\\%$."},{"id":"MCQ-MD-147","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Mở rộng tương tác 3 gen","q":"Ở một loài thực vật, chiều cao cây do 3 cặp gen $(Aa, Bb, Dd)$ nằm trên 2 cặp NST (trong đó $Aa$ nằm trên NST 1, còn $Bb$ và $Dd$ liên kết hoàn toàn trên NST 2). Mỗi alen trội làm cây cao thêm $5\\text{ cm}$, cây thấp nhất cao $120\\text{ cm}$. Khi cho cây có kiểu gen $Aa\\frac{BD}{bd}$ tự thụ phấn, cây cao $135\\text{ cm}$ ở đời $F_1$ chiếm tỉ lệ bao nhiêu?","opts":["$\\frac{3}{8}$ ($37.5\\%$).","$\\frac{1}{4}$ ($25\\%$).","$\\frac{5}{16}$ ($31.25\\%$).","$\\frac{1}{8}$ ($12.5\\%$)."],"ans":1,"exp":"Cây cao $135\\text{ cm}$ cần $\\frac{135 - 120}{5} = 3$ alen trội. Cặp 1 ($Aa\\times Aa$): $\\frac{1}{4}AA$ ($2$ trội) : $\\frac{2}{4}Aa$ ($1$ trội) : $\\frac{1}{4}aa$ ($0$ trội). Cặp 2 ($\\frac{BD}{bd}\\times\\frac{BD}{bd}$ liên kết hoàn toàn): $\\frac{1}{4}\\frac{BD}{BD}$ ($4$ trội) : $\\frac{2}{4}\\frac{BD}{bd}$ ($2$ trội) : $\\frac{1}{4}\\frac{bd}{bd}$ ($0$ trội). Để tổng $= 3$ trội, chỉ có duy nhất $Aa$ ($1$ trội) $\\times$ $\\frac{BD}{bd}$ ($2$ trội) $= \\frac{2}{4} \\times \\frac{2}{4} = \\frac{4}{16} = \\frac{1}{4}$!"},{"id":"MCQ-MD-148","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền Bất hoạt X & Đồng hợp","q":"Bệnh máu khó đông A ở người do đột biến gen lặn yếu tố VIII ($X^h$) trên NST X. Ở một cặp vợ chồng: người vợ bình thường dị hợp ($X^H X^h$) và người chồng bình thường ($X^H Y$). Tuy nhiên, họ sinh được một bé gái có bộ NST $45, X$ (Turner) VÀ bị mắc bệnh máu khó đông A ($X^h O$). Sự bất thường không phân ly NST giới tính nhiều khả năng đã xảy ra ở người nào?","opts":["Ở người MẸ tạo trứng $O$ kết hợp tinh trùng $X^h$ của bố.","Ở người BỐ trong giảm phân (tạo tinh trùng $O$ không mang NST X hay Y), kết hợp với trứng bình thường mang $X^h$ của người mẹ.","Do đột biến ở cặp NST số 21.","Ở người MẸ trong giảm phân II (tạo trứng $X^h X^h$)."],"ans":1,"exp":"Người bố bình thường $X^H Y$ không hề mang alen bệnh $X^h$, nên chiếc $X^h$ duy nhất của cô bé bắt buộc phải nhận từ người mẹ ($X^H X^h$). Điều này chứng tỏ tinh trùng từ bố đã bị thiếu NST giới tính (tinh trùng $O$)."},{"id":"MCQ-MD-149","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hoán vị gen ở Thực vật","q":"Cho phép lai $P: \\frac{AB}{ab} \\times \\frac{AB}{ab}$, biết hoán vị gen xảy ra ở cả 2 giới với tần số $f = 40\\%$ và các gen trội hoàn toàn. Tỉ lệ cá thể ở đời con $F_1$ vừa mang kiểu hình trội cả hai tính trạng ($A-B-$) vừa có kiểu gen ĐỒNG HỢP về ít nhất $1$ cặp gen là bao nhiêu?","opts":["$26\\%$.","$59\\%$.","$33\\%$.","$24\\%$."],"ans":2,"exp":"Giao tử mỗi bên: $0.3\\underline{AB} : 0.3\\underline{ab} : 0.2\\underline{Ab} : 0.2\\underline{aB}$. Trong nhóm $A-B-$, các kiểu gen đồng hợp ít nhất 1 cặp gồm: $\\frac{AB}{AB} = 0.3^2 = 9\\%$; $\\frac{AB}{Ab} = 2(0.3\\times 0.2) = 12\\%$; $\\frac{AB}{aB} = 2(0.3\\times 0.2) = 12\\%$. Tổng $= 9\\% + 12\\% + 12\\% = 33\\%$."},{"id":"MCQ-MD-150","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền Liên kết 3 gen & Thống kê","q":"Ở một loài thực vật, $3$ gen liên kết nằm trên cùng 1 NST theo thứ tự $A - B - D$ với khoảng cách $d(A-B) = 10\\text{ cM}$ và $d(B-D) = 20\\text{ cM}$. Nếu không có hiện tượng nhiễu NST ($I = 0$, $C = 1$), khi cho cây dị hợp $\\frac{ABD}{abd}$ tự thụ phấn (giả sử HVG xảy ra ở cả 2 giới với tần số như nhau), tỉ lệ cây con đồng hợp lặn cả 3 tính trạng ($\\frac{abd}{abd}$) ở $F_1$ xấp xỉ là:","opts":["$12.25\\%$.","$10.89\\%$.","$12.96\\%$.","$16.00\\%$."],"ans":2,"exp":"Xác suất KHÔNG xảy ra trao đổi chéo ở cả vùng I ($0.10$) lẫn vùng II ($0.20$) khi $I=0$ là $(1 - 0.10)(1 - 0.20) = 0.9 \\times 0.8 = 0.72$. Giao tử $\\underline{abd} = \\frac{0.72}{2} = 0.36$. Vậy $\\frac{abd}{abd} = (0.36)^2 = 0.1296 = 12.96\\%$."}];
